# -*- coding: utf-8 -*-
"""Category Replicator - SINGLE-FILE backend (generated by build_single.py; do not edit).
Paste into the webapp Python pane. Needs only the managed-folder variable REPLICATOR_FOLDER."""
import sys, types

def _load(pkg, name, src):
    full = pkg if name == "__init__" else pkg + "." + name
    if pkg not in sys.modules:
        p = types.ModuleType(pkg); p.__path__ = []; sys.modules[pkg] = p
    m = sys.modules[pkg] if name == "__init__" else types.ModuleType(full)
    m.__package__ = pkg
    if name != "__init__":
        sys.modules[full] = m; setattr(sys.modules[pkg], name, m)
    exec(compile(src, full, "exec"), m.__dict__)

_load('replicator_formulas', '__init__', '"""Formula translation + evaluation helpers (copied from the Category Formula Studio)."""\n')

_load('replicator_formulas', 'formula_translate', '"""Best-effort Excel-formula -> Python/pandas expression translator **plus a formula AST**.\n\nThe translator output is a *suggestion*: the Admin UI shows it in an editable textarea\nnext to the original formula, and the admin fixes anything the translator could not\nhandle. Every generated expression runs in the restricted namespace built by\n``compute.evaluate`` which provides: ``df`` (canonical + already-computed columns),\n``np``, ``pd``, the helpers ``IF AND OR NOT ROUND ROUNDUP ROUNDDOWN ABS INT MOD SQRT\nPOWER MIN MAX SUM AVERAGE COUNT CONCAT LEFT RIGHT MID LEN UPPER LOWER TRIM TEXT VALUE\nYEAR MONTH DAY TODAY NOW ISBLANK ISNUMBER ISERROR IFERROR VLOOKUP CELL`` and ``PARAM``\n(toggle/named-value accessor).\n\nFormulas are expected in the *generalized* form produced by ``sample_parser`` where the\ndata row number has been replaced by the ``{r}`` placeholder (e.g. ``=C{r}*D{r}``).\n\nTwo entry points, one grammar:\n\n* ``translate(formula, headers) -> (python_expr, notes)`` - the string the Admin UI edits.\n* ``parse_ast(formula, headers) -> (Node, notes)`` - the same parse as a tree the\n  *tracer* (``formula_trace``) walks node-by-node.  ``Node.to_python()`` renders exactly\n  the string ``translate`` returns, so the two never drift (locked by\n  ``tests/test_formula_ast.py``).\n"""\n\nfrom __future__ import annotations\n\nimport re\nfrom typing import Dict, List, Optional, Tuple\n\n_TOKEN_SPEC = [\n    ("WS", r"\\s+"),\n    ("STRING", r\'"(?:[^"]|"")*"\'),\n    ("SHEETRANGE", r"(?:\'[^\']+\'|[A-Za-z_][A-Za-z0-9_ ]*)!\\$?[A-Za-z]{1,3}\\$?\\d+:\\$?[A-Za-z]{1,3}\\$?\\d+"),\n    ("SHEETCELL", r"(?:\'[^\']+\'|[A-Za-z_][A-Za-z0-9_ ]*)!\\$?[A-Za-z]{1,3}\\$?\\d+"),\n    ("TOKREF", r"\\{tok:[^}]*\\}"),\n    ("RELCELL", r"\\$?[A-Za-z]{1,3}\\{r\\}"),\n    ("ABSCELL", r"\\$?[A-Za-z]{1,3}\\$?\\d+"),\n    ("NUMBER", r"\\d+(?:\\.\\d+)?(?:[eE][+-]?\\d+)?"),\n    ("FUNC", r"[A-Za-z_][A-Za-z0-9_.]*(?=\\s*\\()"),\n    ("IDENT", r"[A-Za-z_][A-Za-z0-9_.]*"),\n    ("OP", r"<>|<=|>=|[-+*/^&=<>]"),\n    ("LPAREN", r"\\("),\n    ("RPAREN", r"\\)"),\n    ("COMMA", r","),\n]\n_MASTER_RE = re.compile("|".join(f"(?P<{n}>{p})" for n, p in _TOKEN_SPEC))\n\n_FUNC_MAP = {\n    "IF": "IF", "IFERROR": "IFERROR", "AND": "AND", "OR": "OR", "NOT": "NOT",\n    "ROUND": "ROUND", "ROUNDUP": "ROUNDUP", "ROUNDDOWN": "ROUNDDOWN",\n    "ABS": "ABS", "INT": "INT", "MOD": "MOD", "SQRT": "SQRT", "POWER": "POWER",\n    "MIN": "MIN", "MAX": "MAX", "SUM": "SUM", "AVERAGE": "AVERAGE", "COUNT": "COUNT",\n    "CONCAT": "CONCAT", "CONCATENATE": "CONCAT",\n    "LEFT": "LEFT", "RIGHT": "RIGHT", "MID": "MID", "LEN": "LEN",\n    "UPPER": "UPPER", "LOWER": "LOWER", "TRIM": "TRIM", "TEXT": "TEXT", "VALUE": "VALUE",\n    "YEAR": "YEAR", "MONTH": "MONTH", "DAY": "DAY", "TODAY": "TODAY", "NOW": "NOW",\n    "ISBLANK": "ISBLANK", "ISNUMBER": "ISNUMBER", "ISERROR": "ISERROR",\n    "COALESCE": "IFERROR",\n}\n\n# Functions the tracer treats specially (short-circuit / branch / error semantics).\nLOGICAL_FUNCS = {"AND", "OR", "NOT"}\n\n\nclass _Tok:\n    __slots__ = ("kind", "val")\n\n    def __init__(self, kind: str, val: str):\n        self.kind, self.val = kind, val\n\n    def __repr__(self):  # pragma: no cover - debug only\n        return f"{self.kind}:{self.val}"\n\n\ndef _tokenize(s: str) -> List[_Tok]:\n    out: List[_Tok] = []\n    pos = 0\n    while pos < len(s):\n        m = _MASTER_RE.match(s, pos)\n        if not m:\n            raise ValueError(f"Cannot tokenize near: {s[pos:pos + 20]!r}")\n        pos = m.end()\n        kind = m.lastgroup\n        if kind == "WS":\n            continue\n        out.append(_Tok(kind, m.group()))\n    return out\n\n\ndef _sheet_name(ref: str) -> str:\n    name = ref.split("!", 1)[0]\n    if name.startswith("\'") and name.endswith("\'"):\n        name = name[1:-1]\n    return name\n\n\n# =========================================================================== AST\nclass Node:\n    """Base class for formula AST nodes.\n\n    ``to_python()`` renders the exact expression string the string-only translator\n    produced.  ``kids()`` yields child nodes (for the tracer\'s tree walk).\n    """\n\n    def to_python(self) -> str:  # pragma: no cover - always overridden\n        raise NotImplementedError\n\n    def kids(self) -> List["Node"]:\n        return []\n\n    def walk(self):\n        yield self\n        for c in self.kids():\n            yield from c.walk()\n\n\nclass Num(Node):\n    def __init__(self, text: str):\n        self.text = text\n\n    def to_python(self) -> str:\n        return self.text\n\n\nclass Bool(Node):\n    def __init__(self, py: str):  # "True" / "False"\n        self.py = py\n\n    def to_python(self) -> str:\n        return self.py\n\n\nclass Nan(Node):\n    def to_python(self) -> str:\n        return "np.nan"\n\n\nclass Str(Node):\n    def __init__(self, value: str):\n        self.value = value\n\n    def to_python(self) -> str:\n        return repr(self.value)\n\n\nclass Col(Node):\n    """A data / already-computed column reference (was ``A{r}``)."""\n\n    def __init__(self, name: str, resolved: bool = True, letter: Optional[str] = None):\n        self.name, self.resolved, self.letter = name, resolved, letter\n\n    def to_python(self) -> str:\n        return f"df[{self.name!r}]"\n\n\nclass FixedCell(Node):\n    """An absolute same-sheet cell (``$B$2``) that cannot be resolved at compute time."""\n\n    def __init__(self, a1: str):\n        self.a1 = a1\n\n    def to_python(self) -> str:\n        return "np.nan"\n\n\nclass SheetCell(Node):\n    def __init__(self, sheet: str, a1: str):\n        self.sheet, self.a1 = sheet, a1\n\n    def to_python(self) -> str:\n        return f"CELL({self.sheet!r}, {self.a1!r})"\n\n\nclass SheetRange(Node):\n    def __init__(self, sheet: str):\n        self.sheet = sheet\n\n    def to_python(self) -> str:\n        return f"LOOKUP_TABLE({self.sheet!r})"\n\n\nclass Param(Node):\n    """A toggle / named value - ``PARAM(\'Name\')`` (from ``{tok:Name}`` or a bare word)."""\n\n    def __init__(self, name: str):\n        self.name = name\n\n    def to_python(self) -> str:\n        return f"PARAM({self.name!r})"\n\n\nclass Paren(Node):\n    def __init__(self, inner: Node):\n        self.inner = inner\n\n    def kids(self):\n        return [self.inner]\n\n    def to_python(self) -> str:\n        return f"({self.inner.to_python()})"\n\n\nclass Unary(Node):\n    def __init__(self, op: str, operand: Node):\n        self.op, self.operand = op, operand\n\n    def kids(self):\n        return [self.operand]\n\n    def to_python(self) -> str:\n        return f"({self.op}{self.operand.to_python()})"\n\n\nclass Bin(Node):\n    """Arithmetic: op in ``+ - * / **``."""\n\n    def __init__(self, op: str, left: Node, right: Node):\n        self.op, self.left, self.right = op, left, right\n\n    def kids(self):\n        return [self.left, self.right]\n\n    def to_python(self) -> str:\n        return f"({self.left.to_python()} {self.op} {self.right.to_python()})"\n\n\nclass Cmp(Node):\n    """Comparison: op already in Python form (``== != < > <= >=``)."""\n\n    def __init__(self, op: str, left: Node, right: Node):\n        self.op, self.left, self.right = op, left, right\n\n    def kids(self):\n        return [self.left, self.right]\n\n    def to_python(self) -> str:\n        return f"({self.left.to_python()} {self.op} {self.right.to_python()})"\n\n\nclass ConcatOp(Node):\n    """The Excel ``&`` operator (left-associative), rendered as nested ``CONCAT(...)``."""\n\n    def __init__(self, left: Node, right: Node):\n        self.left, self.right = left, right\n\n    def kids(self):\n        return [self.left, self.right]\n\n    def to_python(self) -> str:\n        return f"CONCAT({self.left.to_python()}, {self.right.to_python()})"\n\n\nclass Call(Node):\n    """A translated function call - ``name`` is the helper name in the eval namespace."""\n\n    def __init__(self, name: str, args: List[Node]):\n        self.name, self.args = name, args\n\n    def kids(self):\n        return list(self.args)\n\n    def to_python(self) -> str:\n        return f"{self.name}({\', \'.join(a.to_python() for a in self.args)})"\n\n\nclass If(Node):\n    """``IF(cond, then[, else])`` - the tracer evaluates only the branch that is taken."""\n\n    def __init__(self, cond: Node, then: Node, els: Optional[Node] = None):\n        self.cond, self.then, self.els = cond, then, els\n\n    def kids(self):\n        return [self.cond, self.then] + ([self.els] if self.els is not None else [])\n\n    def to_python(self) -> str:\n        parts = [self.cond.to_python(), self.then.to_python()]\n        if self.els is not None:\n            parts.append(self.els.to_python())\n        return f"IF({\', \'.join(parts)})"\n\n\nclass Vlookup(Node):\n    def __init__(self, key: Node, sheet: str, col_index: Node, approx: Node):\n        self.key, self.sheet, self.col_index, self.approx = key, sheet, col_index, approx\n\n    def kids(self):\n        return [self.key, self.col_index, self.approx]\n\n    def to_python(self) -> str:\n        return (f"VLOOKUP({self.key.to_python()}, {self.sheet!r}, "\n                f"{self.col_index.to_python()}, {self.approx.to_python()})")\n\n\nclass Manual(Node):\n    """A function that needs a hand-written pandas expression (INDEX/MATCH/...)."""\n\n    def __init__(self, fname: str):\n        self.fname = fname\n\n    def to_python(self) -> str:\n        return f"MANUAL({self.fname!r})"\n\n\n# =========================================================================== parser\nclass _Parser:\n    def __init__(self, tokens: List[_Tok], header_by_letter: Dict[str, str]):\n        self.toks = tokens\n        self.i = 0\n        self.headers = header_by_letter\n        self.notes: List[str] = []\n\n    # -- token helpers\n    def _peek(self):\n        return self.toks[self.i] if self.i < len(self.toks) else None\n\n    def _next(self):\n        t = self.toks[self.i]\n        self.i += 1\n        return t\n\n    def _eat(self, kind):\n        t = self._peek()\n        if not t or t.kind != kind:\n            raise ValueError(f"Expected {kind}, got {t}")\n        return self._next()\n\n    def _op_is(self, *vals):\n        t = self._peek()\n        return bool(t and t.kind == "OP" and t.val in vals)\n\n    # -- grammar\n    def parse(self) -> Node:\n        return self._concat()\n\n    def _concat(self) -> Node:\n        left = self._compare()\n        while self._op_is("&"):\n            self._next()\n            left = ConcatOp(left, self._compare())\n        return left\n\n    def _compare(self) -> Node:\n        left = self._addsub()\n        while self._op_is("=", "<>", "<", ">", "<=", ">="):\n            op = self._next().val\n            py = {"=": "==", "<>": "!="}.get(op, op)\n            left = Cmp(py, left, self._addsub())\n        return left\n\n    def _addsub(self) -> Node:\n        left = self._muldiv()\n        while self._op_is("+", "-"):\n            op = self._next().val\n            left = Bin(op, left, self._muldiv())\n        return left\n\n    def _muldiv(self) -> Node:\n        left = self._power()\n        while self._op_is("*", "/"):\n            op = self._next().val\n            left = Bin(op, left, self._power())\n        return left\n\n    def _power(self) -> Node:\n        left = self._unary()\n        while self._op_is("^"):\n            self._next()\n            left = Bin("**", left, self._unary())\n        return left\n\n    def _unary(self) -> Node:\n        t = self._peek()\n        if t and t.kind == "OP" and t.val in ("-", "+"):\n            self._next()\n            return Unary(t.val, self._unary())\n        return self._primary()\n\n    def _primary(self) -> Node:\n        t = self._peek()\n        if t is None:\n            raise ValueError("Unexpected end of formula")\n        if t.kind == "LPAREN":\n            self._next()\n            inner = self._concat()\n            self._eat("RPAREN")\n            return Paren(inner)\n        if t.kind == "NUMBER":\n            return Num(self._next().val)\n        if t.kind == "STRING":\n            raw = self._next().val[1:-1].replace(\'""\', \'"\')\n            return Str(raw)\n        if t.kind == "FUNC":\n            return self._funccall()\n        if t.kind == "TOKREF":\n            raw = self._next().val\n            return Param(raw[len("{tok:"): -1])\n        if t.kind == "RELCELL":\n            letter = self._next().val.split("{")[0].replace("$", "").upper()\n            col = self.headers.get(letter)\n            if col is None:\n                self.notes.append(f"column letter {letter} not in the data schema")\n                return Col(letter, resolved=False, letter=letter)\n            return Col(col, resolved=True, letter=letter)\n        if t.kind == "ABSCELL":\n            self._next()\n            self.notes.append(\n                f"fixed cell {t.val} on the data sheet cannot be resolved at compute time"\n            )\n            return FixedCell(t.val.replace("$", ""))\n        if t.kind == "SHEETCELL":\n            self._next()\n            sheet = _sheet_name(t.val)\n            a1 = t.val.split("!", 1)[1].replace("$", "")\n            return SheetCell(sheet, a1)\n        if t.kind == "SHEETRANGE":\n            self._next()\n            return SheetRange(_sheet_name(t.val))\n        if t.kind == "IDENT":\n            name = self._next().val\n            if name.upper() in ("TRUE", "FALSE"):\n                return Bool(name.capitalize())\n            return Param(name)\n        raise ValueError(f"Unexpected token {t}")\n\n    def _funccall(self) -> Node:\n        fname = self._next().val.upper()\n        self._eat("LPAREN")\n        args: List[Node] = []\n        if self._peek() and self._peek().kind != "RPAREN":\n            while True:\n                args.append(self._concat())\n                if self._peek() and self._peek().kind == "COMMA":\n                    self._next()\n                    continue\n                break\n        self._eat("RPAREN")\n\n        if fname == "VLOOKUP":\n            sheet = None\n            if len(args) > 1:\n                for nd in args[1].walk():\n                    if isinstance(nd, (SheetRange, SheetCell)):\n                        sheet = nd.sheet\n                        break\n            key = args[0] if args else Nan()\n            col_index = args[2] if len(args) > 2 else Num("2")\n            approx = args[3] if len(args) > 3 else Bool("False")\n            if sheet is None:\n                self.notes.append("VLOOKUP table is not a Sheet!range reference")\n                sheet = "UNKNOWN"\n            return Vlookup(key, sheet, col_index, approx)\n\n        if fname in ("HLOOKUP", "INDEX", "MATCH", "XLOOKUP", "LOOKUP"):\n            self.notes.append(f"{fname} needs manual translation")\n            return Manual(fname)\n\n        if fname in ("TRUE", "FALSE"):\n            return Bool(fname.capitalize())\n\n        if fname == "IFS":\n            # IFS(c1,v1,c2,v2,...) -> nested IF\n            self.notes.append("IFS converted to nested IF")\n            node: Node = Nan()\n            for k in range(len(args) - 2, -1, -2):\n                node = If(args[k], args[k + 1], node)\n            return node\n\n        if fname == "IF":\n            if len(args) >= 3:\n                return If(args[0], args[1], args[2])\n            if len(args) == 2:\n                return If(args[0], args[1], None)\n            return Call("IF", args)  # 0/1 args: keep whatever the old path produced\n\n        mapped = _FUNC_MAP.get(fname)\n        if mapped is None:\n            self.notes.append(f"unknown function {fname} kept as-is")\n            mapped = fname\n        return Call(mapped, args)\n\n\n# =========================================================================== API\ndef _strip(excel_formula: str) -> str:\n    s = excel_formula.strip()\n    return s[1:] if s.startswith("=") else s\n\n\ndef parse_ast(excel_formula: str, header_by_letter: Dict[str, str]) -> Tuple[Node, List[str]]:\n    """Parse ``excel_formula`` (generalized, ``{r}`` form) into an AST.\n\n    Returns ``(root_node, notes)``.  Raises ``ValueError`` if the formula cannot be\n    tokenized / parsed - callers that need the soft-failure string use ``translate``.\n    """\n    parser = _Parser(_tokenize(_strip(excel_formula)), header_by_letter)\n    root = parser.parse()\n    if parser.i != len(parser.toks):\n        parser.notes.append("trailing tokens were ignored")\n    return root, parser.notes\n\n\ndef translate(excel_formula: str, header_by_letter: Dict[str, str]) -> Tuple[str, List[str]]:\n    """Return ``(python_expression, notes)``. Never raises - failures land in ``notes``."""\n    s = _strip(excel_formula)\n    if not s:\n        return "np.nan", ["empty formula"]\n    try:\n        root, notes = parse_ast(excel_formula, header_by_letter)\n        return root.to_python(), notes\n    except Exception as exc:  # noqa: BLE001 - best effort, surface to admin\n        return f"np.nan  # TODO translate: {s}", [f"could not parse: {exc}"]\n')

_load('replicator_formulas', 'sample_parser', '"""Analyse an uploaded sample workbook.\n\nThe sample ``.xlsx`` holds, on separate sheets:\n  * one **data sheet** whose rows may start at any row (header auto-detected);\n  * some columns of that data sheet contain **Excel formulas** -> "computed" columns;\n  * other sheets are **lookup / mapping tables** referenced by the formulas;\n  * formulas may reference **toggle** names that are neither columns nor lookup sheets.\n\n``analyze_sample(bytes)`` returns a plain dict the Admin UI renders for review/editing.\nOnly openpyxl + (optional) the sibling ``formula_translate`` module are used - no dataiku.\n"""\n\nfrom __future__ import annotations\n\nimport io\nimport re\nimport string\nfrom typing import Any, Dict, List, Optional, Tuple\n\nimport openpyxl\n\nfrom . import formula_translate\n\nMAX_SCAN_ROWS = 40\n_CELL_RE = re.compile(r"(\\$?)([A-Za-z]{1,3})(\\$?)(\\d+)")\n_SHEET_REF_RE = re.compile(r"(?:\'([^\']+)\'|([A-Za-z_][A-Za-z0-9_ ]*))!")\n# A sheet-qualified single cell OR range (e.g. "Rates!$A$2" / "Rates!$A$2:$B$4") - matched\n# as one unit so range-generalisation never mistakes the range\'s second cell for a\n# same-sheet "fixed cell" (see generalize_formula).\n_SHEET_QUALIFIED_RE = re.compile(\n    _SHEET_REF_RE.pattern + _CELL_RE.pattern + r"(?::" + _CELL_RE.pattern + r")?"\n)\n_FUNC_RE = re.compile(r"([A-Za-z][A-Za-z0-9_.]*)\\s*\\(")\n_TOKEN_RE = re.compile(r"[A-Za-z_][A-Za-z0-9_]*")\n# sheets named "Toggle", "Toggle 1", "Toggles 2" ... hold the Yes/No switches (like the\n# lookup/mapping sheets hold reference tables).\n_TOGGLE_SHEET_RE = re.compile(r"^\\s*toggles?\\s*[-_ ]?\\d*\\s*$", re.I)\n_YESNO = {"yes": "Yes", "y": "Yes", "true": "Yes", "1": "Yes",\n          "no": "No", "n": "No", "false": "No", "0": "No"}\n_GENERIC_LABELS = {"name", "value", "toggle", "toggles", "key", "parameter",\n                   "param", "setting", "switch", "flag"}\n\n\ndef is_toggle_sheet(name: str) -> bool:\n    return bool(_TOGGLE_SHEET_RE.match(name or ""))\n\n\ndef _split_sheet_cell(text: str) -> Tuple[str, str]:\n    sheet, a1 = text.split("!", 1)\n    if sheet.startswith("\'") and sheet.endswith("\'"):\n        sheet = sheet[1:-1]\n    return sheet, a1.replace("$", "")\n\n# Excel built-ins we translate / recognise; never treated as toggles.\nKNOWN_FUNCS = {\n    "IF", "IFS", "IFERROR", "AND", "OR", "NOT", "ROUND", "ROUNDUP", "ROUNDDOWN",\n    "ABS", "MIN", "MAX", "SUM", "AVERAGE", "COUNT", "INT", "MOD", "SQRT", "POWER",\n    "VLOOKUP", "HLOOKUP", "INDEX", "MATCH", "LOOKUP", "XLOOKUP",\n    "CONCAT", "CONCATENATE", "LEFT", "RIGHT", "MID", "LEN", "UPPER", "LOWER", "TRIM",\n    "TEXT", "VALUE", "TODAY", "NOW", "YEAR", "MONTH", "DAY", "DATE", "TRUE", "FALSE",\n    "ISBLANK", "ISNUMBER", "ISERROR", "COALESCE",\n}\n\n\n# --------------------------------------------------------------------------- utils\ndef col_letter_to_index(letter: str) -> int:\n    """``A`` -> 0, ``B`` -> 1, ``AA`` -> 26 ..."""\n    n = 0\n    for ch in letter.upper():\n        n = n * 26 + (ord(ch) - ord("A") + 1)\n    return n - 1\n\n\ndef col_index_to_letter(idx: int) -> str:\n    idx += 1\n    out = ""\n    while idx > 0:\n        idx, rem = divmod(idx - 1, 26)\n        out = string.ascii_uppercase[rem] + out\n    return out\n\n\ndef _norm(v: Any) -> str:\n    return re.sub(r"\\s+", " ", str(v)).strip() if v is not None else ""\n\n\ndef _looks_like_label(v: Any) -> bool:\n    s = _norm(v)\n    if not s:\n        return False\n    try:\n        float(s.replace(",", ""))\n        return False\n    except ValueError:\n        return True\n\n\ndef detect_header_row(rows: List[List[Any]], max_scan: int = MAX_SCAN_ROWS) -> int:\n    """Return the 0-based index of the most likely header row.\n\n    Heuristic: the row with the most distinct non-empty text cells that also has a\n    non-empty data row beneath it and no empty cells between its populated columns.\n    """\n    best_idx, best_score = 0, -1.0\n    limit = min(len(rows), max_scan)\n    for i in range(limit):\n        row = rows[i]\n        labels = [c for c in row if _looks_like_label(c)]\n        non_null = [c for c in row if _norm(c)]\n        if len(labels) < 2:\n            continue\n        nxt = rows[i + 1] if i + 1 < len(rows) else []\n        has_data_below = any(_norm(c) for c in nxt)\n        distinct = len({_norm(c).lower() for c in labels})\n        score = distinct + 0.5 * len(non_null)\n        if has_data_below:\n            score += 3\n        if len(labels) == len(non_null):  # header row is usually all-text\n            score += 1\n        if score > best_score:\n            best_idx, best_score = i, score\n    return best_idx\n\n\ndef _sheet_rows(ws, values_only: bool = True) -> List[List[Any]]:\n    return [list(r) for r in ws.iter_rows(values_only=values_only)]\n\n\ndef _headers_from_row(row: List[Any]) -> List[str]:\n    headers, seen = [], {}\n    for j, cell in enumerate(row):\n        name = _norm(cell) or f"Column{col_index_to_letter(j)}"\n        if name in seen:\n            seen[name] += 1\n            name = f"{name}.{seen[name]}"\n        else:\n            seen[name] = 0\n        headers.append(name)\n    return headers\n\n\n# ------------------------------------------------------------------- formula tools\n_TOK_PLACEHOLDER_RE = re.compile(r"\\{tok:[^}]*\\}")\n\n\ndef extract_refs(formula: str) -> Dict[str, List[str]]:\n    """Split a formula into referenced sheet names, function names and bare tokens."""\n    sheets = sorted({m.group(1) or m.group(2) for m in _SHEET_REF_RE.finditer(formula)})\n    funcs = sorted({m.group(1).upper() for m in _FUNC_RE.finditer(formula)})\n    # Strip string literals, sheet-qualified refs and {tok:...} placeholders before\n    # scanning bare tokens (a placeholder\'s own text must not look like a new token).\n    stripped = re.sub(r\'"[^"]*"\', "", formula)\n    stripped = _SHEET_REF_RE.sub("", stripped)\n    stripped = _TOK_PLACEHOLDER_RE.sub("", stripped)\n    stripped = _CELL_RE.sub("", stripped)\n    tokens = sorted(\n        {\n            t for t in _TOKEN_RE.findall(stripped)\n            if t.upper() not in KNOWN_FUNCS and not re.fullmatch(r"[A-Za-z]{1,3}\\d*", t)\n        }\n    )\n    return {"sheets": sheets, "funcs": funcs, "tokens": tokens}\n\n\ndef generalize_formula(\n    formula: str, row: int, header_letters: Dict[str, str],\n    fixed_cell_hook: Optional[Any] = None,\n    sheet_cell_hook: Optional[Any] = None,\n) -> str:\n    """Replace same-sheet cell refs on ``row`` with the ``{r}`` placeholder.\n\n    ``A5`` on row 5 -> ``A{r}``. Any other same-sheet cell ref - an absolute ``$A$5``, or\n    a plain ref that points at a different row (a stray look-elsewhere reference) - is\n    "fixed": it stays constant across rows, so it can\'t become ``{r}``. Such a ref is\n    typically a single labelled parameter/toggle cell placed elsewhere on the sheet\n    (e.g. ``IF($AB$2="Yes", ...)``). By default it is left as-is; pass ``fixed_cell_hook``\n    (called with ``(raw_text, col_letters, row_num)``) to substitute something else, e.g.\n    a ``{tok:Name}`` placeholder once that cell has been registered as a toggle.\n\n    ``sheet_cell_hook(sheet_name, cell_a1, raw_text)`` is called for every *sheet-qualified\n    single cell* (``\'Toggle 1\'!$B$2``); return a replacement string (e.g. ``{tok:Name}``)\n    or ``None`` to leave it untouched. Sheet-qualified *ranges* (VLOOKUP tables) are always\n    left alone.\n    """\n    def repl(m: re.Match) -> str:\n        dollar_col, col, dollar_row, rownum = m.groups()\n        if dollar_row != "$" and int(rownum) == row:\n            return f"{dollar_col}{col}{{r}}"\n        if fixed_cell_hook:\n            return fixed_cell_hook(m.group(0), col.upper(), int(rownum))\n        return m.group(0)\n\n    # Protect sheet-qualified refs from row generalisation (but let the sheet-cell hook\n    # rewrite single-cell refs, e.g. a toggle-sheet reference -> {tok:Name}).\n    placeholders: Dict[str, str] = {}\n\n    def stash(m: re.Match) -> str:\n        text = m.group(0)\n        if sheet_cell_hook and ":" not in text:\n            sheet, a1 = _split_sheet_cell(text)\n            replacement = sheet_cell_hook(sheet, a1, text)\n            if replacement is not None:\n                return replacement\n        key = f"\\x00{len(placeholders)}\\x00"\n        placeholders[key] = text\n        return key\n\n    protected = _SHEET_QUALIFIED_RE.sub(stash, formula)\n\n    # Same-sheet ranges (SUMIFS($C$2:$C$40, ...)) are not "fixed parameter cells": keep them verbatim, except\n    # a same-row range like A5:C5 which is row-relative.\n    def range_stash(m: re.Match) -> str:\n        a, b = m.group(1), m.group(2)\n        ma, mb = _CELL_RE.fullmatch(a), _CELL_RE.fullmatch(b)\n        if ma and mb and ma.group(3) != "$" and mb.group(3) != "$" and int(ma.group(4)) == row == int(mb.group(4)):\n            return "%s%s{r}:%s%s{r}" % (ma.group(1), ma.group(2), mb.group(1), mb.group(2))\n        key = f"\\x00{len(placeholders)}\\x00"\n        placeholders[key] = m.group(0)\n        return key\n    protected = re.sub(r"(\\$?[A-Za-z]{1,3}\\$?\\d+):(\\$?[A-Za-z]{1,3}\\$?\\d+)", range_stash, protected)\n    generalized = _CELL_RE.sub(repl, protected)\n    for key, val in placeholders.items():\n        generalized = generalized.replace(key, val)\n    return generalized\n\n\ndef _guess_cell_label(ws_v, row_num: int, col_idx: int) -> Optional[str]:\n    """A fixed cell is usually a value next to a text label - e.g. \'Include Tax\' in the\n    cell to its left, or above it. Used to name the toggle after that label."""\n    candidates = []\n    if col_idx > 0:\n        candidates.append(ws_v.cell(row=row_num, column=col_idx).value)  # left neighbour\n    if row_num > 1:\n        candidates.append(ws_v.cell(row=row_num - 1, column=col_idx + 1).value)  # above\n    for v in candidates:\n        if _looks_like_label(v):\n            return _norm(v)\n    return None\n\n\ndef _guess_toggle_value(raw: Any) -> str:\n    s = _norm(raw).lower()\n    return "Yes" if s in ("yes", "true", "y", "1") else "No"\n\n\n# ------------------------------------------------------------------------- analyse\ndef analyze_sample(file_bytes: bytes, data_sheet: Optional[str] = None) -> Dict[str, Any]:\n    """Parse the sample workbook. See module docstring for the return shape."""\n    wb_f = openpyxl.load_workbook(io.BytesIO(file_bytes), data_only=False)\n    wb_v = openpyxl.load_workbook(io.BytesIO(file_bytes), data_only=True)\n    warnings: List[str] = []\n\n    # 1. pick the data sheet: explicit choice, else the sheet with the most formula cells,\n    #    else the sheet with the largest populated area.\n    def formula_count(ws) -> int:\n        c = 0\n        for r in ws.iter_rows():\n            for cell in r:\n                if isinstance(cell.value, str) and cell.value.startswith("="):\n                    c += 1\n        return c\n\n    sheet_names = wb_f.sheetnames\n    if data_sheet and data_sheet in sheet_names:\n        ds_name = data_sheet\n    else:\n        scored = sorted(\n            sheet_names,\n            key=lambda n: (formula_count(wb_f[n]), wb_f[n].max_row * wb_f[n].max_column),\n            reverse=True,\n        )\n        ds_name = scored[0]\n        if formula_count(wb_f[ds_name]) == 0:\n            warnings.append(\n                "No Excel formula cells were found on any sheet; "\n                f"\'{ds_name}\' was chosen by size. Pick the data sheet manually if wrong."\n            )\n\n    ws_f, ws_v = wb_f[ds_name], wb_v[ds_name]\n    frows = _sheet_rows(ws_f)\n    vrows = _sheet_rows(ws_v)\n    if not frows:\n        raise ValueError(f"Data sheet \'{ds_name}\' is empty.")\n\n    header_row = detect_header_row(vrows)\n    first_data = header_row + 1\n    if first_data >= len(frows):\n        raise ValueError(f"Data sheet \'{ds_name}\' has a header but no data rows.")\n\n    # Keep only columns that are actually part of the table: a header label, or data\n    # underneath it. openpyxl pads every row out to the sheet\'s overall max_column, so\n    # without this a cell placed far to the right (e.g. a toggle at $AB$2) would drag in\n    # dozens of blank "ColumnF".."ColumnAB" placeholders as bogus canonical columns.\n    raw_header_row = frows[header_row]\n\n    def _col_has_data(j: int) -> bool:\n        return any(j < len(r) and _norm(r[j]) for r in frows[first_data:])\n\n    kept = [j for j in range(len(raw_header_row))\n           if _norm(raw_header_row[j]) or _col_has_data(j)]\n    headers = _headers_from_row([raw_header_row[j] for j in kept])\n    letter_by_header = {h: col_index_to_letter(kept[i]) for i, h in enumerate(headers)}\n    header_by_letter = {col_index_to_letter(kept[i]): h for i, h in enumerate(headers)}\n\n    # 2. toggles + column classification.\n    #\n    # Toggles (Yes/No switches used in formulas) can come from:\n    #   (a) a dedicated "Toggle" / "Toggle 1" ... sheet holding name/value rows, OR\n    #   (b) a single labelled cell placed elsewhere on the data sheet\n    #       (``IF($AB$2="Yes", ...)``), OR\n    #   (c) a bare word used directly in a formula (``IF(IncludeTax, ...)``).\n    # All three feed one ``toggle_defs`` map: name -> {name, value, [sheet], [cell]}.\n    # Formula references to (a)/(b) are templated to ``{tok:Name}`` so they survive both\n    # the pandas translation and rebuilding the live Excel formula.\n    toggle_defs: Dict[str, Dict[str, Any]] = {}\n    used_names: Dict[str, str] = {}\n    sheet_cell_to_toggle: Dict[Tuple[str, Optional[str]], str] = {}\n    toggle_sheet_names = {\n        n for n in sheet_names if n != ds_name and is_toggle_sheet(n)\n    }\n\n    def _register_toggle(name: str, value: str, sheet=None, cell=None, tag=None, raw=None, anchored=None) -> str:\n        tag = tag or (f"{sheet}!{cell}" if sheet else cell or name)\n        base, cand = name, name\n        i = 2\n        while used_names.get(cand, tag) != tag:\n            cand = f"{base} ({i})"\n            i += 1\n        used_names[cand] = tag\n        entry = {"name": cand, "value": value}\n        if sheet:\n            entry["sheet"] = sheet\n        if cell:\n            entry["cell"] = cell\n        if anchored is not None:\n            entry["anchored"] = anchored\n            entry["raw"] = raw if isinstance(raw, (str, int, float, bool)) or raw is None else str(raw)\n        toggle_defs.setdefault(cand, entry)\n        return cand\n\n    for tname in sorted(toggle_sheet_names):\n        trows = _sheet_rows(wb_v[tname])\n        got = False\n        for ri, trow in enumerate(trows):\n            key = _norm(trow[0]) if trow else ""\n            val = _norm(trow[1]) if len(trow) > 1 else ""\n            if key and key.lower() not in _GENERIC_LABELS and val.lower() in _YESNO:\n                nm = _register_toggle(key, _YESNO[val.lower()], sheet=tname,\n                                      cell=f"B{ri + 1}")\n                sheet_cell_to_toggle[(tname, f"B{ri + 1}")] = nm\n                sheet_cell_to_toggle.setdefault((tname, None), nm)\n                got = True\n        if not got:  # fall back: first Yes/No cell anywhere on the sheet\n            for ri, trow in enumerate(trows):\n                for ci, cell in enumerate(trow):\n                    if _norm(cell).lower() in _YESNO:\n                        addr = f"{col_index_to_letter(ci)}{ri + 1}"\n                        nm = _register_toggle(tname, _YESNO[_norm(cell).lower()],\n                                              sheet=tname, cell=addr)\n                        sheet_cell_to_toggle[(tname, addr)] = nm\n                        sheet_cell_to_toggle.setdefault((tname, None), nm)\n                        got = True\n                        break\n                if got:\n                    break\n\n    def _fixed_cell_hook(raw_text: str, col_letters: str, row_num: int) -> str:\n        addr = f"{col_letters}{row_num}"\n        key = ("__data__", addr)\n        if key not in sheet_cell_to_toggle:\n            col_idx = col_letter_to_index(col_letters)\n            try:\n                raw_value = ws_v.cell(row=row_num, column=col_idx + 1).value\n            except Exception:  # noqa: BLE001\n                raw_value = None\n            label = _guess_cell_label(ws_v, row_num, col_idx) or f"Cell {addr}"\n            sheet_cell_to_toggle[key] = _register_toggle(\n                label, _guess_toggle_value(raw_value), cell=addr, tag=addr,\n                raw=raw_value, anchored=("$" in raw_text),\n            )\n        return "{tok:%s}" % sheet_cell_to_toggle[key]\n\n    def _sheet_cell_hook(sheet: str, a1: str, raw_text: str):\n        if sheet not in toggle_sheet_names:\n            return None  # a lookup-sheet cell, or anything else - leave it alone\n        name = (sheet_cell_to_toggle.get((sheet, a1))\n                or sheet_cell_to_toggle.get((sheet, None)))\n        if not name:\n            name = _register_toggle(sheet, "Yes", sheet=sheet, cell=a1)\n            sheet_cell_to_toggle[(sheet, a1)] = name\n        return "{tok:%s}" % name\n\n    canonical: List[str] = []\n    computed: List[Dict[str, Any]] = []\n    for j, name in enumerate(headers):\n        orig_j = kept[j]\n        formula_cell = None\n        formula_excel_row = None\n        for ridx in range(first_data, len(frows)):\n            val = frows[ridx][orig_j] if orig_j < len(frows[ridx]) else None\n            if isinstance(val, str) and val.startswith("="):\n                formula_cell = val\n                formula_excel_row = ridx + 1  # openpyxl rows are 1-based\n                break\n        if formula_cell is None:\n            canonical.append(name)\n            continue\n        generalized = generalize_formula(\n            formula_cell, formula_excel_row, letter_by_header,\n            _fixed_cell_hook, _sheet_cell_hook,\n        )\n        pandas_expr, xl_notes = formula_translate.translate(\n            generalized, header_by_letter\n        )\n        refs = extract_refs(generalized)\n        computed.append(\n            {\n                "name": name,\n                "position": j,\n                "excel_formula": generalized,\n                "sample_excel_formula": formula_cell,\n                "sample_row": formula_excel_row,\n                "pandas_expr": pandas_expr,\n                "refs": refs,\n                "notes": xl_notes,\n            }\n        )\n\n    if not computed:\n        warnings.append("No computed (formula) columns detected on the data sheet.")\n\n    # 3. lookup sheets = every other sheet that isn\'t a toggle sheet\n    lookups: List[Dict[str, Any]] = []\n    for name in sheet_names:\n        if name == ds_name or name in toggle_sheet_names:\n            continue\n        lrows = _sheet_rows(wb_v[name])\n        if not any(any(_norm(c) for c in row) for row in lrows):\n            continue\n        lhr = detect_header_row(lrows)\n        lheaders = _headers_from_row(lrows[lhr]) if lrows else []\n        preview = [\n            {lheaders[k]: row[k] if k < len(row) else None for k in range(len(lheaders))}\n            for row in lrows[lhr + 1: lhr + 6]\n        ]\n        lookups.append(\n            {\n                "sheet": name,\n                "header_row": lhr,\n                "columns": lheaders,\n                "preview": preview,\n                "n_rows": max(0, len(lrows) - lhr - 1),\n            }\n        )\n    lookup_sheet_names = {l["sheet"] for l in lookups}\n\n    # 4. bare-word tokens -> toggle candidates, merged with the sheet/fixed-cell toggles\n    # already found while generalizing the formulas (step 2, above).\n    canon_lower = {c.lower() for c in canonical}\n    comp_lower = {c["name"].lower() for c in computed}\n    for c in computed:\n        for tok in c["refs"]["tokens"]:\n            tl = tok.lower()\n            if tl in canon_lower or tl in comp_lower:\n                continue\n            if tok in lookup_sheet_names or tok in toggle_sheet_names:\n                continue\n            if tok not in toggle_defs:\n                toggle_defs[tok] = {"name": tok, "value": "Yes"}\n        for sh in c["refs"]["sheets"]:\n            if sh not in lookup_sheet_names and sh not in toggle_sheet_names:\n                warnings.append(\n                    f"Column \'{c[\'name\']}\' references sheet \'{sh}\' which is not a "\n                    "lookup sheet in the workbook."\n                )\n\n    # 5. name-collision guard (computed columns must be distinct from data columns)\n    collisions = comp_lower & canon_lower\n    if collisions:\n        warnings.append(\n            "Computed columns reuse data-column names: "\n            + ", ".join(sorted(collisions))\n            + ". Rename them so comparisons can address each side."\n        )\n\n    return {\n        "sheets": sheet_names,\n        "data_sheet": ds_name,\n        "header_row": header_row,\n        "canonical_schema": canonical,\n        "computed_columns": computed,\n        "lookups": lookups,\n        "toggle_sheets": sorted(toggle_sheet_names),\n        "toggles": list(toggle_defs.values()),\n        "warnings": warnings,\n    }\n\n\ndef sheet_to_records(file_bytes: bytes, sheet: str) -> Tuple[List[str], List[Dict[str, Any]]]:\n    """Return ``(headers, rows-as-dicts)`` for one sheet, header auto-detected.\n\n    Used by the backend to persist each lookup sheet into the mapping folder.\n    """\n    wb = openpyxl.load_workbook(io.BytesIO(file_bytes), data_only=True)\n    rows = _sheet_rows(wb[sheet])\n    hr = detect_header_row(rows)\n    headers = _headers_from_row(rows[hr]) if rows else []\n    records = []\n    for row in rows[hr + 1:]:\n        if not any(_norm(c) for c in row):\n            continue\n        records.append(\n            {headers[k]: (row[k] if k < len(row) else None) for k in range(len(headers))}\n        )\n    return headers, records\n')

_load('replicator_formulas', 'compute', '"""Validate an input file against a category recipe, evaluate the computed columns and\nbuild the output workbook (canonical values + **live Excel formulas** in the computed\ncolumns + lookup sheets + a Parameters sheet).\n\nPure module: inputs are bytes / dicts, outputs are bytes / DataFrames. No ``dataiku``.\n"""\n\nfrom __future__ import annotations\n\nimport io\nimport re\nfrom typing import Any, Dict, List, Optional, Tuple\n\nimport numpy as np\nimport pandas as pd\nimport openpyxl\nfrom openpyxl.utils import get_column_letter\n\nfrom .sample_parser import detect_header_row, _headers_from_row, _norm, col_letter_to_index\n\n_A1_RE = re.compile(r"^\\$?([A-Za-z]{1,3})\\$?(\\d+)$")\n_TOK_RE = re.compile(r"\\{tok:([^}]+)\\}")\n\n\n_SCAN_ROWS = 60\n\n\ndef _nkey(s: Any) -> str:\n    return re.sub(r"\\s+", " ", str(s)).strip().lower() if s is not None else ""\n\n\n# --------------------------------------------------------------------------- input IO\ndef read_table(file_bytes: bytes, filename: str,\n               expected_columns: Optional[List[str]] = None) -> Tuple[pd.DataFrame, int]:\n    """Read csv / xls / xlsx into a DataFrame.\n\n    When ``expected_columns`` (the category\'s canonical schema) is given, the table is\n    located by NAME: the header row is the one matching the most canonical names, and only\n    the columns spanning those matched headers are kept. Anything sitting elsewhere on the\n    sheet - a toggle/parameter cell like ``$AB$2``, notes, a totals block - is left out, so\n    it can\'t be mistaken for an extra column and fail the schema check.\n\n    Without ``expected_columns`` it falls back to generic header auto-detection.\n    """\n    name = (filename or "").lower()\n    if name.endswith(".csv") or name.endswith(".txt"):\n        raw = pd.read_csv(io.BytesIO(file_bytes), header=None, dtype=object,\n                          keep_default_na=False, skip_blank_lines=False)\n        rows = raw.values.tolist()\n    else:\n        engine = "xlrd" if name.endswith(".xls") else "openpyxl"\n        raw = pd.read_excel(io.BytesIO(file_bytes), header=None, dtype=object, engine=engine)\n        rows = raw.values.tolist()\n    if not rows:\n        raise ValueError(f"{filename}: no rows found")\n    rows = [[None if pd.isna(c) else c for c in r] for r in rows]\n\n    if expected_columns:\n        want = {_nkey(c) for c in expected_columns}\n        scored = [\n            (sum(1 for c in row if _nkey(c) in want), -i, i)\n            for i, row in enumerate(rows[:_SCAN_ROWS])\n        ]\n        hits, _, hr = max(scored)\n        if hits > 0:\n            matched = [j for j, c in enumerate(rows[hr]) if _nkey(c) in want]\n            lo, hi = min(matched), max(matched)\n            headers = _headers_from_row([c for c in rows[hr][lo:hi + 1]])\n            # the table is the contiguous block under the header - stop at the first\n            # blank row (which normally separates it from a totals/notes block below).\n            body = []\n            for r in rows[hr + 1:]:\n                cells = r[lo:hi + 1]\n                if not any(_norm(c) for c in cells):\n                    break\n                body.append(cells)\n            df = pd.DataFrame(body, columns=headers)\n            return df.reset_index(drop=True), hr\n        # no canonical header found: return the generic read so validate_schema can\n        # report a clear "missing / unexpected" message rather than a crash.\n\n    hr = detect_header_row(rows)\n    headers = _headers_from_row(rows[hr])\n    df = pd.DataFrame(rows[hr + 1:], columns=headers).dropna(axis=0, how="all").reset_index(drop=True)\n    df = df.loc[:, [not (h.startswith("Column") and df[h].isna().all()) for h in df.columns]]\n    return df, hr\n\n\ndef validate_schema(columns: List[str], canonical_schema: List[str]) -> Dict[str, Any]:\n    """Exact match: same columns, same order, nothing extra (case/space-insensitive)."""\n    def key(s: str) -> str:\n        return re.sub(r"\\s+", " ", str(s)).strip().lower()\n\n    got = [key(c) for c in columns]\n    want = [key(c) for c in canonical_schema]\n    got_set, want_set = set(got), set(want)\n    missing = [c for c in canonical_schema if key(c) not in got_set]\n    extra = [c for c in columns if key(c) not in want_set]\n    order_ok = got == want\n    ok = not missing and not extra and order_ok\n    if ok:\n        msg = "Schema matches."\n    else:\n        parts = []\n        if missing:\n            parts.append("missing: " + ", ".join(missing))\n        if extra:\n            parts.append("unexpected: " + ", ".join(extra))\n        if not missing and not extra and not order_ok:\n            parts.append("column order differs from the sample")\n        msg = "; ".join(parts)\n    return {"ok": ok, "missing": missing, "extra": extra,\n            "order_ok": order_ok, "message": msg}\n\n\n# ------------------------------------------------------------------------- lookups\nclass Lookups:\n    """Access to the category\'s lookup tables (persisted from the sample\'s mapping sheets).\n\n    ``tables`` maps sheet name -> ``{"headers": [...], "records": [ {..}, .. ],\n    "header_row": int}``.\n    """\n\n    def __init__(self, tables: Dict[str, Dict[str, Any]]):\n        self._t = tables or {}\n        self._df_cache: Dict[str, pd.DataFrame] = {}\n        self._grid_cache: Dict[str, List[List[Any]]] = {}\n\n    def has(self, name: str) -> bool:\n        return name in self._t\n\n    def df(self, name: str) -> pd.DataFrame:\n        if name not in self._df_cache:\n            spec = self._t.get(name)\n            if not spec:\n                raise KeyError(f"lookup sheet \'{name}\' is not defined for this category")\n            self._df_cache[name] = pd.DataFrame(spec["records"], columns=spec["headers"])\n        return self._df_cache[name]\n\n    def grid(self, name: str) -> List[List[Any]]:\n        if name not in self._grid_cache:\n            spec = self._t[name]\n            hr = int(spec.get("header_row", 0))\n            grid: List[List[Any]] = [[] for _ in range(hr)]\n            grid.append(list(spec["headers"]))\n            for rec in spec["records"]:\n                grid.append([rec.get(h) for h in spec["headers"]])\n            self._grid_cache[name] = grid\n        return self._grid_cache[name]\n\n    def cell(self, name: str, a1: str) -> Any:\n        m = _A1_RE.match(a1.strip())\n        if not m:\n            raise ValueError(f"bad cell reference {a1!r}")\n        col = col_letter_to_index(m.group(1))\n        row = int(m.group(2)) - 1\n        grid = self.grid(name)\n        if row < len(grid) and col < len(grid[row]):\n            return grid[row][col]\n        return np.nan\n\n    def vlookup(self, key, name: str, col_index: int, approximate: bool = False):\n        frame = self.df(name)\n        if frame.shape[1] < col_index:\n            raise ValueError(f"VLOOKUP col index {col_index} out of range for \'{name}\'")\n        keys = frame.iloc[:, 0]\n        vals = frame.iloc[:, int(col_index) - 1]\n        mapping = dict(zip(keys, vals))\n        if isinstance(key, pd.Series):\n            if approximate:\n                sorted_keys = np.sort(keys.values)\n                idx = np.searchsorted(sorted_keys, key.values, side="right") - 1\n                idx = np.clip(idx, 0, len(sorted_keys) - 1)\n                approx_keys = sorted_keys[idx]\n                return pd.Series([mapping.get(k, np.nan) for k in approx_keys],\n                                 index=key.index)\n            return key.map(mapping)\n        return mapping.get(key, np.nan)\n\n\n# ---------------------------------------------------------------- eval helper funcs\ndef _series_index(*args):\n    for a in args:\n        if isinstance(a, pd.Series):\n            return a.index\n    return None\n\n\ndef _as_frame(args, index):\n    cols = []\n    for a in args:\n        cols.append(a if isinstance(a, pd.Series) else pd.Series([a] * len(index), index=index))\n    return pd.concat(cols, axis=1)\n\n\ndef IF(cond, a, b):\n    if not isinstance(cond, (pd.Series, np.ndarray)):       # a single switch (toggle / constant), not a column\n        cond = False if (isinstance(cond, float) and np.isnan(cond)) else bool(cond)\n    idx = _series_index(cond, a, b)\n    if idx is not None:\n        return pd.Series(np.where(cond, a, b), index=idx)\n    return a if cond else b\n\n\ndef IFERROR(value, fallback):\n    if isinstance(value, pd.Series):\n        return value.where(value.notna() & ~value.isin([np.inf, -np.inf]), fallback)\n    try:\n        if value is None or (isinstance(value, float) and (np.isnan(value) or np.isinf(value))):\n            return fallback\n        return value\n    except TypeError:\n        return value\n\n\ndef _reduce_logical(op, args, empty):\n    idx = _series_index(*args)\n    if idx is None:\n        res = empty\n        for a in args:\n            res = op(res, bool(a))\n        return res\n    frame = _as_frame(args, idx).astype(bool)\n    out = frame.iloc[:, 0]\n    for c in range(1, frame.shape[1]):\n        out = op(out, frame.iloc[:, c])\n    return out\n\n\ndef AND(*args):\n    return _reduce_logical(np.logical_and, args, True)\n\n\ndef OR(*args):\n    return _reduce_logical(np.logical_or, args, False)\n\n\ndef NOT(x):\n    return ~x if isinstance(x, pd.Series) else (not x)\n\n\ndef _rowwise(func, args):\n    idx = _series_index(*args)\n    if idx is None:\n        return func([a for a in args])\n    return _as_frame(args, idx).apply(lambda r: func(list(r.values)), axis=1)\n\n\ndef MIN(*a):\n    return _rowwise(lambda xs: np.nanmin(pd.to_numeric(pd.Series(xs), errors="coerce")), a)\n\n\ndef MAX(*a):\n    return _rowwise(lambda xs: np.nanmax(pd.to_numeric(pd.Series(xs), errors="coerce")), a)\n\n\ndef SUM(*a):\n    return _rowwise(lambda xs: np.nansum(pd.to_numeric(pd.Series(xs), errors="coerce")), a)\n\n\ndef AVERAGE(*a):\n    return _rowwise(lambda xs: np.nanmean(pd.to_numeric(pd.Series(xs), errors="coerce")), a)\n\n\ndef COUNT(*a):\n    return _rowwise(lambda xs: pd.to_numeric(pd.Series(xs), errors="coerce").notna().sum(), a)\n\n\ndef ROUND(x, n=0):\n    """Excel ROUND: half away from zero, on the number as Excel sees it (15 significant digits)."""\n    v = pd.to_numeric(x, errors="coerce") if isinstance(x, pd.Series) else x\n    f = 10.0 ** int(n)\n    scaled = np.round(np.abs(v) * f, 6)          # strip binary noise like 127923.49999999999\n    return np.sign(v) * np.floor(scaled + 0.5) / f\n\n\ndef ROUNDUP(x, n=0):\n    f = 10 ** int(n)\n    return np.ceil((x if not isinstance(x, pd.Series) else pd.to_numeric(x, errors="coerce")) * f) / f\n\n\ndef ROUNDDOWN(x, n=0):\n    f = 10 ** int(n)\n    return np.floor((x if not isinstance(x, pd.Series) else pd.to_numeric(x, errors="coerce")) * f) / f\n\n\ndef ABS(x):\n    return x.abs() if isinstance(x, pd.Series) else abs(x)\n\n\ndef INT(x):\n    return np.floor(pd.to_numeric(x, errors="coerce")) if isinstance(x, pd.Series) else int(x)\n\n\ndef MOD(a, b):\n    return a % b\n\n\ndef SQRT(x):\n    return np.sqrt(x)\n\n\ndef POWER(x, p):\n    return x ** p\n\n\ndef _str_series(x):\n    return x.astype("string") if isinstance(x, pd.Series) else pd.Series([str(x)])\n\n\ndef CONCAT(*args):\n    idx = _series_index(*args)\n    if idx is None:\n        return "".join("" if a is None else str(a) for a in args)\n    frame = _as_frame(args, idx)\n    return frame.apply(lambda r: "".join("" if v is None else str(v) for v in r.values), axis=1)\n\n\ndef LEFT(x, n=1):\n    return x.astype("string").str[: int(n)] if isinstance(x, pd.Series) else str(x)[: int(n)]\n\n\ndef RIGHT(x, n=1):\n    return x.astype("string").str[-int(n):] if isinstance(x, pd.Series) else str(x)[-int(n):]\n\n\ndef MID(x, start, length):\n    s = int(start) - 1\n    if isinstance(x, pd.Series):\n        return x.astype("string").str[s: s + int(length)]\n    return str(x)[s: s + int(length)]\n\n\ndef LEN(x):\n    return x.astype("string").str.len() if isinstance(x, pd.Series) else len(str(x))\n\n\ndef UPPER(x):\n    return x.astype("string").str.upper() if isinstance(x, pd.Series) else str(x).upper()\n\n\ndef LOWER(x):\n    return x.astype("string").str.lower() if isinstance(x, pd.Series) else str(x).lower()\n\n\ndef TRIM(x):\n    return x.astype("string").str.strip() if isinstance(x, pd.Series) else str(x).strip()\n\n\ndef TEXT(x, _fmt=None):\n    return x.astype("string") if isinstance(x, pd.Series) else str(x)\n\n\ndef VALUE(x):\n    return pd.to_numeric(x, errors="coerce")\n\n\ndef _dt(x):\n    return pd.to_datetime(x, errors="coerce")\n\n\ndef YEAR(x):\n    return _dt(x).dt.year if isinstance(x, pd.Series) else _dt(x).year\n\n\ndef MONTH(x):\n    return _dt(x).dt.month if isinstance(x, pd.Series) else _dt(x).month\n\n\ndef DAY(x):\n    return _dt(x).dt.day if isinstance(x, pd.Series) else _dt(x).day\n\n\ndef TODAY():\n    return pd.Timestamp.today().normalize()\n\n\ndef NOW():\n    return pd.Timestamp.now()\n\n\ndef ISBLANK(x):\n    return x.isna() | (x.astype("string").str.len() == 0) if isinstance(x, pd.Series) else (x is None or x == "")\n\n\ndef ISNUMBER(x):\n    return pd.to_numeric(x, errors="coerce").notna() if isinstance(x, pd.Series) else isinstance(x, (int, float))\n\n\ndef ISERROR(x):\n    return x.isna() if isinstance(x, pd.Series) else (x is None)\n\n\n# ------------------------------------------------------------------------- evaluate\nclass ToggleValue(str):\n    """A toggle\'s value, usable both ways a formula might use it:\n\n    * as text - ``IF($AB$2="Yes", ...)`` -> ``PARAM(\'X\') == \'Yes\'`` (plain string equality,\n      since this *is* a ``str``), and\n    * as a boolean - ``IF(IncludeTax, ...)`` -> ``IF(PARAM(\'X\'), ...)`` (truthy only for\n      Yes/True/Y/1, via the overridden ``__bool__``).\n    """\n\n    def __bool__(self) -> bool:\n        return self.strip().lower() in ("yes", "true", "y", "1")\n\n    def __eq__(self, other):\n        if isinstance(other, bool):          # IF(Toggle!B2=TRUE, ...)\n            return bool(self) == other\n        return str.__eq__(self, other)\n\n    def __ne__(self, other):\n        return not self.__eq__(other)\n\n    __hash__ = str.__hash__\n\n\ndef _toggle_value(raw: Any) -> ToggleValue:\n    return ToggleValue("" if raw is None else str(raw))\n\n\ndef evaluate(df: pd.DataFrame, recipe: Dict[str, Any],\n             lookups: Optional[Lookups] = None) -> pd.DataFrame:\n    """Return a copy of ``df`` with the recipe\'s computed columns appended (values)."""\n    lookups = lookups or Lookups({})\n    toggles = {t["name"]: _toggle_value(t.get("value")) for t in recipe.get("toggles", [])}\n    work = df.copy()\n    # numeric coercion for canonical columns keeps arithmetic sane; keep original too.\n    ns = {\n        "np": np, "pd": pd, "df": work,\n        "IF": IF, "IFERROR": IFERROR, "AND": AND, "OR": OR, "NOT": NOT,\n        "MIN": MIN, "MAX": MAX, "SUM": SUM, "AVERAGE": AVERAGE, "COUNT": COUNT,\n        "ROUND": ROUND, "ROUNDUP": ROUNDUP, "ROUNDDOWN": ROUNDDOWN, "ABS": ABS,\n        "INT": INT, "MOD": MOD, "SQRT": SQRT, "POWER": POWER,\n        "CONCAT": CONCAT, "LEFT": LEFT, "RIGHT": RIGHT, "MID": MID, "LEN": LEN,\n        "UPPER": UPPER, "LOWER": LOWER, "TRIM": TRIM, "TEXT": TEXT, "VALUE": VALUE,\n        "YEAR": YEAR, "MONTH": MONTH, "DAY": DAY, "TODAY": TODAY, "NOW": NOW,\n        "ISBLANK": ISBLANK, "ISNUMBER": ISNUMBER, "ISERROR": ISERROR,\n        "CELL": lookups.cell,\n        "VLOOKUP": lambda key, sheet, col_index, approx=False: lookups.vlookup(\n            key, sheet, col_index, bool(approx)),\n        "LOOKUP_TABLE": lookups.df,\n        "PARAM": lambda name: toggles.get(name, toggles.get(str(name), np.nan)),\n        "MANUAL": lambda fn: (_ for _ in ()).throw(\n            ValueError(f"formula uses {fn} which needs a manual pandas expression")),\n    }\n    errors: List[str] = []\n    for col in sorted(recipe.get("computed_columns", []), key=lambda c: c.get("position", 1e9)):\n        expr = col.get("pandas_expr") or "np.nan"\n        try:\n            result = eval(expr, {"__builtins__": {}}, ns)  # noqa: S307 - trusted admin config\n        except Exception as exc:  # noqa: BLE001\n            errors.append(f"{col[\'name\']}: {exc}")\n            result = np.nan\n        work[col["name"]] = result\n        ns["df"] = work\n    if errors:\n        work.attrs["compute_errors"] = errors\n    return work\n\n\n# -------------------------------------------------------------------- output workbook\ndef ordered_columns(recipe: Dict[str, Any]) -> List[str]:\n    canonical = list(recipe.get("canonical_schema", []))\n    computed = sorted(recipe.get("computed_columns", []), key=lambda c: c.get("position", 1e9))\n    total = len(canonical) + len(computed)\n    slots: List[Optional[str]] = [None] * total\n    for c in computed:\n        pos = c.get("position")\n        if isinstance(pos, int) and 0 <= pos < total and slots[pos] is None:\n            slots[pos] = c["name"]\n    it = iter(canonical)\n    for i in range(total):\n        if slots[i] is None:\n            slots[i] = next(it, None)\n    # any leftovers (bad positions) appended\n    leftover = [c["name"] for c in computed if c["name"] not in slots] + [c for c in it]\n    return [s for s in slots if s] + leftover\n\n\ndef build_workbook(values_df: pd.DataFrame, recipe: Dict[str, Any],\n                   lookups: Optional[Lookups] = None,\n                   data_sheet_name: str = "Data") -> bytes:\n    """Build the output ``.xlsx``: computed columns carry the live Excel formula."""\n    lookups = lookups or Lookups({})\n    cols = [c for c in ordered_columns(recipe) if c in values_df.columns] or list(values_df.columns)\n    computed_by_name = {c["name"]: c for c in recipe.get("computed_columns", [])}\n    # a computed formula\'s {tok:Name} placeholders (see sample_parser\'s fixed-cell\n    # detection) point at whichever row that toggle ends up on in the Parameters sheet.\n    toggle_row = {t["name"]: i + 2 for i, t in enumerate(recipe.get("toggles", []))}\n\n    def _resolve_tokens(formula: str) -> str:\n        return _TOK_RE.sub(\n            lambda m: f"Parameters!$B${toggle_row[m.group(1)]}"\n            if m.group(1) in toggle_row else "FALSE()",\n            formula,\n        )\n\n    wb = openpyxl.Workbook()\n    ws = wb.active\n    ws.title = data_sheet_name[:31]\n    ws.append(cols)\n    for r_off, (_, row) in enumerate(values_df.iterrows()):\n        excel_row = r_off + 2\n        out_row = []\n        for c in cols:\n            if c in computed_by_name:\n                formula = computed_by_name[c].get("excel_formula", "")\n                if formula:\n                    formula = _resolve_tokens(formula.replace("{r}", str(excel_row)))\n                out_row.append(formula if formula else row.get(c))\n            else:\n                val = row.get(c)\n                out_row.append(None if (isinstance(val, float) and np.isnan(val)) else val)\n        ws.append(out_row)\n\n    # lookup sheets\n    for name, spec in getattr(lookups, "_t", {}).items():\n        sh = wb.create_sheet(title=str(name)[:31])\n        for _ in range(int(spec.get("header_row", 0))):\n            sh.append([])\n        sh.append(list(spec["headers"]))\n        for rec in spec["records"]:\n            sh.append([rec.get(h) for h in spec["headers"]])\n\n    # parameters\n    toggles = recipe.get("toggles", [])\n    if toggles:\n        ps = wb.create_sheet(title="Parameters")\n        ps.append(["Name", "Value"])\n        for t in toggles:\n            ps.append([t["name"], t.get("value")])\n\n    buf = io.BytesIO()\n    wb.save(buf)\n    return buf.getvalue()\n\n\ndef lookups_from_sample(analysis: Dict[str, Any], file_bytes: bytes) -> Dict[str, Dict[str, Any]]:\n    """Build the persisted lookup-table spec dict from a sample analysis + the file bytes."""\n    from .sample_parser import sheet_to_records\n    tables: Dict[str, Dict[str, Any]] = {}\n    for lk in analysis.get("lookups", []):\n        headers, records = sheet_to_records(file_bytes, lk["sheet"])\n        tables[lk["sheet"]] = {\n            "headers": headers, "records": records,\n            "header_row": lk.get("header_row", 0),\n        }\n    return tables\n')

_load('replicator', '__init__', '"""Category Replicator core: learn column rules from examples and replay them on new data."""\n')

_load('replicator', 'rules', '"""Rule engine: one *rule* describes how to build one output column.\n\nA rule is a plain JSON dict (so it can be stored, shown and edited):\n\n    {"name": "Risk Weight", "kind": "lookup", ...kind specific fields..., "source": "inferred"}\n\nKinds\n    copy         {"col"}\n    const        {"value"}\n    text         {"col", "fn": upper|lower|strip|title|left|right|mid|str, "n", "start"}\n    datepart     {"col", "part": year|month|day|quarter|monthname|weekday|ym|fmt, "fmt"}\n    arith        {"expr": <node>, "round": int|None, "on_error": value|None}\n                 node = {"col"} | {"const"} | {"lookup": <lookup spec>} |\n                        {"op": + - * /, "l": node, "r": node} | {"fn": abs|max|min, "args": [node..]}\n    concat       {"parts": [{"col"} | {"text"}]}\n    lookup       {"table", "keys": [cols], "table_keys": [cols], "value", "default", "approx"}\n    cond         {"tree"}   tree = {"test": {"col","op","value"}, "then": tree, "else": tree}\n                 or a leaf {"leaf": {"const"} | {"col"}}\n    learned_map  {"keys": [cols], "pairs": [[k.., v]], "default"}\n    formula      {"pandas_expr", "excel_formula"}   (Excel formula translated by the Studio parser,\n                 or a manual pandas expression)\n\nEverything here is dataiku-free and vectorised over a pandas DataFrame (``work``).\n"""\n\nfrom __future__ import annotations\n\nimport datetime as dt\nimport math\nimport re\nfrom typing import Any, Callable, Dict, List, Optional, Tuple\n\nimport numpy as np\nimport pandas as pd\n\n_WS = re.compile(r"\\s+")\n\n\nclass RuleError(Exception):\n    pass\n\n\n# ------------------------------------------------------------------ scalar helpers\ndef is_blank(v: Any) -> bool:\n    if v is None:\n        return True\n    if isinstance(v, float) and math.isnan(v):\n        return True\n    if v is pd.NaT:\n        return True\n    if isinstance(v, str) and v.strip() == "":\n        return True\n    return False\n\n\ndef disp(v: Any) -> str:\n    """Excel-ish text rendering of a value (integers lose the \'.0\')."""\n    if is_blank(v):\n        return ""\n    if isinstance(v, bool):\n        return "TRUE" if v else "FALSE"\n    if isinstance(v, (int, np.integer)):\n        return str(int(v))\n    if isinstance(v, (float, np.floating)):\n        f = float(v)\n        return str(int(f)) if f.is_integer() else repr(f)\n    if isinstance(v, (dt.datetime, pd.Timestamp)):\n        return v.strftime("%Y-%m-%d") if (v.hour, v.minute, v.second) == (0, 0, 0) else v.isoformat(" ")\n    if isinstance(v, dt.date):\n        return v.isoformat()\n    return str(v)\n\n\ndef nk(v: Any) -> str:\n    """Normalised comparison/lookup key: case-, space- and 1 vs 1.0-insensitive."""\n    return _WS.sub(" ", disp(v)).strip().lower()\n\n\ndef key_series(s: pd.Series) -> pd.Series:\n    return s.map(nk)\n\n\ndef to_num(s: pd.Series) -> pd.Series:\n    """Excel arithmetic coercion: numbers stay, blanks -> 0, text that is not a number -> NaN."""\n    blank = s.map(is_blank)\n    out = pd.to_numeric(s.where(~blank), errors="coerce")\n    return out.where(~blank, 0.0).astype(float)\n\n\ndef numeric_share(s: pd.Series) -> float:\n    if pd.api.types.is_datetime64_any_dtype(s):   # dates are not numbers (pandas would turn them into ns ints)\n        return 0.0\n    nb = ~s.map(is_blank)\n    if not nb.any():\n        return 0.0\n    return float(pd.to_numeric(s[nb], errors="coerce").notna().mean())\n\n\ndef to_dates(s: pd.Series) -> pd.Series:\n    def one(v):\n        if is_blank(v):\n            return pd.NaT\n        if isinstance(v, (dt.datetime, dt.date, pd.Timestamp)):\n            return pd.Timestamp(v)\n        if isinstance(v, (int, float, np.integer, np.floating)):\n            return pd.NaT\n        try:\n            return pd.Timestamp(pd.to_datetime(str(v), errors="raise"))\n        except Exception:  # noqa: BLE001\n            return pd.NaT\n    return pd.to_datetime(s.map(one), errors="coerce")\n\n\ndef date_share(s: pd.Series) -> float:\n    nb = ~s.map(is_blank)\n    if not nb.any():\n        return 0.0\n    return float(to_dates(s[nb]).notna().mean())\n\n\ndef eq_series(pred: pd.Series, expect: pd.Series) -> pd.Series:\n    """Cell-by-cell \'same value?\' with Excel-friendly tolerance."""\n    p = pred.reset_index(drop=True)\n    y = expect.reset_index(drop=True)\n    pb, yb = p.map(is_blank), y.map(is_blank)\n    pn = pd.to_numeric(p.where(~pb), errors="coerce")\n    yn = pd.to_numeric(y.where(~yb), errors="coerce")\n    both = pn.notna() & yn.notna()\n    numeq = pd.Series(np.isclose(pn.fillna(0).values, yn.fillna(0).values, rtol=1e-7, atol=1e-6),\n                      index=p.index)\n    streq = p.map(lambda v: disp(v).strip()) == y.map(lambda v: disp(v).strip())\n    return (both & numeq) | (~both & streq) | (pb & yb)\n\n\n# ------------------------------------------------------------------------ context\nclass Ctx:\n    """Tables (name -> DataFrame) + toggles + small caches, shared by every rule."""\n\n    def __init__(self, tables: Optional[Dict[str, pd.DataFrame]] = None,\n                 toggles: Optional[List[Dict[str, Any]]] = None):\n        self.tables: Dict[str, pd.DataFrame] = tables or {}\n        self.toggles = toggles or []\n        self._idx: Dict[Tuple, Dict] = {}\n        self.notes: List[str] = []            # run-time warnings (unmapped keys ...)\n        self.stats: Dict[str, Dict[str, Any]] = {}\n\n    def table(self, name: str) -> pd.DataFrame:\n        if name in self.tables:\n            return self.tables[name]\n        low = {k.lower(): k for k in self.tables}\n        if name.lower() in low:\n            return self.tables[low[name.lower()]]\n        raise RuleError(f"mapping table \'{name}\' is not available")\n\n    def index(self, table: str, keys: List[str]) -> Dict:\n        ck = (table, tuple(keys))\n        if ck not in self._idx:\n            df = self.table(table)\n            cols = [resolve_col(df, k) for k in keys]\n            kk = [key_series(df[c]) for c in cols]\n            idx: Dict = {}\n            for i, tup in enumerate(zip(*kk)):\n                idx.setdefault(tup, i)\n            self._idx[ck] = idx\n        return self._idx[ck]\n\n\ndef resolve_col(df: pd.DataFrame, name: str) -> str:\n    if name in df.columns:\n        return name\n    low = {nk(c): c for c in df.columns}\n    if nk(name) in low:\n        return low[nk(name)]\n    raise RuleError(f"column \'{name}\' not found")\n\n\ndef get_col(work: pd.DataFrame, name: str) -> pd.Series:\n    return work[resolve_col(work, name)]\n\n\n# -------------------------------------------------------------- lookup application\ndef lookup_series(spec: Dict[str, Any], work: pd.DataFrame, ctx: Ctx,\n                  rule_name: str = "") -> pd.Series:\n    df = ctx.table(spec["table"])\n    vcol = resolve_col(df, spec["value"])\n    vals = df[vcol].tolist()\n    keys = spec["keys"]\n    if spec.get("approx"):\n        kcol = resolve_col(df, spec["table_keys"][0])\n        tk = pd.to_numeric(df[kcol], errors="coerce")\n        order = np.argsort(tk.fillna(np.inf).values, kind="stable")\n        sk = tk.values[order]\n        x = to_num(get_col(work, keys[0])).values\n        pos = np.searchsorted(sk, x, side="right") - 1\n        out = [vals[order[p]] if p >= 0 and not math.isnan(xx) else np.nan for p, xx in zip(pos, x)]\n        return pd.Series(out, index=work.index, dtype=object)\n    idx = ctx.index(spec["table"], spec["table_keys"])\n    kcols = [key_series(get_col(work, k)) for k in keys]\n    default = spec.get("default")\n    out, miss = [], 0\n    missing_keys: Dict[str, int] = {}\n    for tup in zip(*kcols):\n        i = idx.get(tup)\n        if i is None:\n            miss += 1\n            out.append(default if default is not None else np.nan)\n            if len(missing_keys) < 8:\n                lab = " | ".join(tup)\n                missing_keys[lab] = missing_keys.get(lab, 0) + 1\n        else:\n            out.append(vals[i])\n    if miss and rule_name:\n        ctx.stats[rule_name] = {"unmatched": miss, "examples": list(missing_keys)[:8]}\n    return pd.Series(out, index=work.index, dtype=object)\n\n\n# ------------------------------------------------------------------ arithmetic tree\ndef _node(node: Dict[str, Any], work: pd.DataFrame, ctx: Ctx) -> pd.Series:\n    if "col" in node:\n        return to_num(get_col(work, node["col"]))\n    if "const" in node:\n        return pd.Series(float(node["const"]), index=work.index)\n    if "lookup" in node:\n        return to_num(lookup_series(node["lookup"], work, ctx))\n    if "fn" in node:\n        args = [_node(a, work, ctx) for a in node["args"]]\n        fn = node["fn"]\n        if fn == "abs":\n            return args[0].abs()\n        if fn == "max":\n            return pd.concat(args, axis=1).max(axis=1)\n        if fn == "min":\n            return pd.concat(args, axis=1).min(axis=1)\n        raise RuleError(f"unknown function {fn}")\n    op = node["op"]\n    l, r = _node(node["l"], work, ctx), _node(node["r"], work, ctx)\n    with np.errstate(all="ignore"):\n        if op == "+":\n            return l + r\n        if op == "-":\n            return l - r\n        if op == "*":\n            return l * r\n        if op == "/":\n            return (l / r).replace([np.inf, -np.inf], np.nan)\n    raise RuleError(f"unknown operator {op}")\n\n\ndef _round_half_up(s: pd.Series, n: int) -> pd.Series:\n    f = 10.0 ** n\n    v = s * f\n    return np.sign(v) * np.floor(np.round(np.abs(v), 6) + 0.5) / f  # Excel ROUND (half away from zero)\n\n\n# ----------------------------------------------------------------------- conditions\ndef cmp_mask(s: pd.Series, op: str, value: Any) -> pd.Series:\n    op = {"=": "==", "<>": "!="}.get(op, op)\n    blank = s.map(is_blank)\n    if op in ("blank", "is empty"):\n        return blank\n    if op in ("not blank", "not empty"):\n        return ~blank\n    if op in ("in", "not in"):\n        vals = value if isinstance(value, list) else [x.strip() for x in str(value).split(",")]\n        m = key_series(s).isin({nk(v) for v in vals})\n        return m if op == "in" else ~m\n    if op in ("contains", "not contains", "startswith", "endswith"):\n        t = key_series(s)\n        v = nk(value)\n        m = {"contains": t.str.contains(re.escape(v), regex=True),\n             "not contains": ~t.str.contains(re.escape(v), regex=True),\n             "startswith": t.str.startswith(v), "endswith": t.str.endswith(v)}[op]\n        return m.fillna(False)\n    vnum = pd.to_numeric(pd.Series([value]), errors="coerce").iloc[0]\n    sn = pd.to_numeric(s.where(~blank), errors="coerce")\n    if op in ("==", "!="):\n        if not pd.isna(vnum) and sn.notna().mean() > 0.5:\n            eq = pd.Series(np.isclose(sn.fillna(np.nan).values, float(vnum), rtol=1e-9, atol=1e-9), index=s.index)\n        else:\n            eq = key_series(s) == nk(value)\n        return eq if op == "==" else ~eq\n    if pd.isna(vnum):\n        a, b = key_series(s), nk(value)\n        return {">": a > b, ">=": a >= b, "<": a < b, "<=": a <= b}[op]\n    return {">": sn > vnum, ">=": sn >= vnum, "<": sn < vnum, "<=": sn <= vnum}[op].fillna(False)\n\n\ndef _leaf(node: Dict[str, Any], work: pd.DataFrame) -> pd.Series:\n    if "const" in node:\n        return pd.Series([node["const"]] * len(work), index=work.index, dtype=object)\n    return get_col(work, node["col"]).astype(object)\n\n\ndef _pair_mask(a: pd.Series, op: str, b: pd.Series) -> np.ndarray:\n    x, y = to_num(a).values, to_num(b).values\n    with np.errstate(invalid="ignore"):\n        return {">": x > y, ">=": x >= y, "<": x < y, "<=": x <= y,\n                "==": np.isclose(x, y, rtol=1e-9, atol=1e-9), "!=": ~np.isclose(x, y, rtol=1e-9, atol=1e-9)}[op]\n\n\ndef _tree(tree: Dict[str, Any], work: pd.DataFrame) -> pd.Series:\n    if "leaf" in tree:\n        return _leaf(tree["leaf"], work)\n    t = tree["test"]\n    if t.get("value_col"):      # compare two columns, e.g. Amount > Threshold\n        m = _pair_mask(get_col(work, t["col"]), t["op"], get_col(work, t["value_col"]))\n    else:\n        m = cmp_mask(get_col(work, t["col"]), t["op"], t.get("value")).values\n    a, b = _tree(tree["then"], work), _tree(tree["else"], work)\n    return pd.Series(np.where(m, a.values, b.values), index=work.index, dtype=object)\n\n\n# -------------------------------------------------------------------------- formula\ndef formula_series(rule: Dict[str, Any], work: pd.DataFrame, ctx: Ctx) -> pd.Series:\n    if rule.get("excel_only"):\n        return pd.Series(np.nan, index=work.index, dtype=object)\n    if rule.get("by_sheet") and rule.get("group"):\n        # the formula differs per split sheet: evaluate every variant, keep each row\'s own one\n        g = rule["group"]\n        grp = get_col(work, g["col"]).map(nk).map(g["map"])\n        names = list(rule["by_sheet"])\n        out = pd.Series(np.nan, index=work.index, dtype=object)\n        first = _formula_one(rule["by_sheet"][names[0]]["pandas_expr"], work, ctx)\n        out[:] = first.values\n        for sh in names[1:]:\n            m = (grp == sh).values\n            if m.any():\n                v = _formula_one(rule["by_sheet"][sh]["pandas_expr"], work, ctx)\n                out[m] = v.values[m]\n        m0 = (grp == names[0]).values\n        return out\n    return _formula_one(rule["pandas_expr"], work, ctx)\n\n\ndef _formula_one(expr: str, work: pd.DataFrame, ctx: Ctx) -> pd.Series:\n    from replicator_formulas import compute  # lazy: keeps rules importable on its own\n    lk = compute.Lookups({\n        n: {"headers": list(df.columns), "records": df.to_dict("records"), "header_row": 0}\n        for n, df in ctx.tables.items()\n    })\n    recipe = {"computed_columns": [{"name": "__out__", "pandas_expr": expr}],\n              "toggles": ctx.toggles}\n    res = compute.evaluate(work, recipe, lk)\n    errs = res.attrs.get("compute_errors")\n    if errs:\n        raise RuleError("; ".join(errs))\n    return res["__out__"]\n\n\n# ----------------------------------------------------------------------- dispatcher\ndef apply_rule(rule: Dict[str, Any], work: pd.DataFrame, ctx: Ctx) -> pd.Series:\n    kind = rule["kind"]\n    n = len(work)\n    if kind == "copy":\n        return get_col(work, rule["col"]).copy()\n    if kind == "const":\n        return pd.Series([rule.get("value")] * n, index=work.index, dtype=object)\n    if kind == "text":\n        s = get_col(work, rule["col"])\n        d = s.map(disp)\n        fn = rule["fn"]\n        k = int(rule.get("n") or 1)\n        out = {"upper": d.str.upper(), "lower": d.str.lower(), "strip": d.str.strip(),\n               "title": d.str.title(), "left": d.str[:k], "right": d.str[-k:] if k else d.str[:0],\n               "mid": d.str[int(rule.get("start", 1)) - 1:int(rule.get("start", 1)) - 1 + k],\n               "str": d}[fn]\n        return out\n    if kind == "datepart":\n        d = to_dates(get_col(work, rule["col"]))\n        part = rule["part"]\n        if part == "year":\n            return d.dt.year.astype(float)\n        if part == "month":\n            return d.dt.month.astype(float)\n        if part == "day":\n            return d.dt.day.astype(float)\n        if part == "quarter":\n            return d.dt.quarter.astype(float)\n        if part == "weekday":\n            return d.dt.day_name()\n        if part == "monthname":\n            return d.dt.month_name()\n        if part == "ym":\n            return d.dt.strftime("%Y-%m")\n        if part == "fmt":\n            return d.dt.strftime(rule["fmt"])\n        raise RuleError(f"unknown date part {part}")\n    if kind == "arith":\n        v = _node(rule["expr"], work, ctx)\n        if rule.get("round") is not None:\n            v = _round_half_up(v, int(rule["round"]))\n        if rule.get("on_error") is not None:\n            v = v.where(v.notna(), rule["on_error"])\n        return v.astype(object).where(v.notna(), np.nan)\n    if kind == "concat":\n        parts = []\n        for p in rule["parts"]:\n            if "col" in p:\n                parts.append(get_col(work, p["col"]).map(disp))\n            else:\n                parts.append(pd.Series(str(p["text"]), index=work.index))\n        out = parts[0]\n        for p in parts[1:]:\n            out = out + p\n        return out\n    if kind == "lookup":\n        return lookup_series(rule, work, ctx, rule.get("name", ""))\n    if kind == "cond":\n        return _tree(rule["tree"], work)\n    if kind == "learned_map":\n        keys = rule["keys"]\n        mp = {tuple(nk(x) for x in p[:-1]): p[-1] for p in rule["pairs"]}\n        cols = [key_series(get_col(work, k)) for k in keys]\n        default = rule.get("default")\n        out, miss, ex = [], 0, []\n        for tup in zip(*cols):\n            if tup in mp:\n                out.append(mp[tup])\n            else:\n                miss += 1\n                out.append(default if default is not None else np.nan)\n                if len(ex) < 8 and " | ".join(tup) not in ex:\n                    ex.append(" | ".join(tup))\n        if miss and rule.get("name"):\n            ctx.stats[rule["name"]] = {"unmatched": miss, "examples": ex}\n        return pd.Series(out, index=work.index, dtype=object)\n    if kind == "formula":\n        return formula_series(rule, work, ctx)\n    raise RuleError(f"unknown rule kind \'{kind}\'")\n\n\n# ------------------------------------------------------------------- introspection\ndef _node_cols(node: Dict[str, Any], out: List[str]) -> None:\n    if "col" in node:\n        out.append(node["col"])\n    elif "lookup" in node:\n        out.extend(node["lookup"]["keys"])\n    elif "fn" in node:\n        for a in node["args"]:\n            _node_cols(a, out)\n    elif "op" in node:\n        _node_cols(node["l"], out)\n        _node_cols(node["r"], out)\n\n\ndef _tree_cols(t: Dict[str, Any], out: List[str]) -> None:\n    if "leaf" in t:\n        if "col" in t["leaf"]:\n            out.append(t["leaf"]["col"])\n        return\n    out.append(t["test"]["col"])\n    if t["test"].get("value_col"):\n        out.append(t["test"]["value_col"])\n    _tree_cols(t["then"], out)\n    _tree_cols(t["else"], out)\n\n\ndef rule_columns(rule: Dict[str, Any]) -> List[str]:\n    """Columns (input or earlier output) this rule reads."""\n    k, out = rule["kind"], []\n    if k in ("copy", "text", "datepart"):\n        out.append(rule["col"])\n    elif k == "arith":\n        _node_cols(rule["expr"], out)\n    elif k == "concat":\n        out.extend(p["col"] for p in rule["parts"] if "col" in p)\n    elif k in ("lookup", "learned_map"):\n        out.extend(rule["keys"])\n    elif k == "cond":\n        _tree_cols(rule["tree"], out)\n    elif k == "formula":\n        exprs = [rule.get("pandas_expr", "")] + [v.get("pandas_expr", "") for v in (rule.get("by_sheet") or {}).values()]\n        for e in exprs:\n            out.extend(re.findall(r"df\\[\\s*[\'\\"]([^\'\\"]+)[\'\\"]\\s*\\]", e))\n        if rule.get("group"):\n            out.append(rule["group"]["col"])\n    return list(dict.fromkeys(out))\n\n\ndef rule_tables(rule: Dict[str, Any]) -> List[str]:\n    out: List[str] = []\n\n    def walk(n):\n        if isinstance(n, dict):\n            if "lookup" in n:\n                out.append(n["lookup"]["table"])\n            for v in n.values():\n                walk(v)\n    if rule["kind"] == "lookup":\n        out.append(rule["table"])\n    walk(rule.get("expr", {}))\n    if rule["kind"] == "formula":\n        for e in [rule.get("pandas_expr", "")] + [v.get("pandas_expr", "") for v in (rule.get("by_sheet") or {}).values()]:\n            out.extend(re.findall(r"VLOOKUP\\([^,]+,\\s*[\'\\"]([^\'\\"]+)[\'\\"]", e))\n    return list(dict.fromkeys(out))\n\n\n# --------------------------------------------------------------------- description\ndef _fmt_const(c: Any) -> str:\n    return disp(c) if not isinstance(c, str) else f\'"{c}"\'\n\n\ndef _desc_node(n: Dict[str, Any]) -> str:\n    if "col" in n:\n        return f"[{n[\'col\']}]"\n    if "const" in n:\n        return _fmt_const(n["const"])\n    if "lookup" in n:\n        lk = n["lookup"]\n        return f"{lk[\'table\']}.{lk[\'value\']}[by {\', \'.join(lk[\'keys\'])}]"\n    if "fn" in n:\n        return f"{n[\'fn\'].upper()}({\', \'.join(_desc_node(a) for a in n[\'args\'])})"\n    return f"({_desc_node(n[\'l\'])} {n[\'op\']} {_desc_node(n[\'r\'])})"\n\n\ndef _desc_tree(t: Dict[str, Any]) -> str:\n    if "leaf" in t:\n        return _desc_node(t["leaf"])\n    x = t["test"]\n    rhs = f"[{x[\'value_col\']}]" if x.get("value_col") else _fmt_const(x.get("value"))\n    return f"IF([{x[\'col\']}] {x[\'op\']} {rhs}, {_desc_tree(t[\'then\'])}, {_desc_tree(t[\'else\'])})"\n\n\ndef describe(rule: Dict[str, Any]) -> str:\n    k = rule["kind"]\n    if k == "copy":\n        return f"Copy of [{rule[\'col\']}]"\n    if k == "const":\n        return f"Constant {_fmt_const(rule.get(\'value\'))}"\n    if k == "text":\n        extra = f", {rule.get(\'n\')}" if rule["fn"] in ("left", "right", "mid") else ""\n        return f"{rule[\'fn\'].upper()}([{rule[\'col\']}]{extra})"\n    if k == "datepart":\n        return f"{rule[\'part\']} of [{rule[\'col\']}]" + (f" ({rule[\'fmt\']})" if rule["part"] == "fmt" else "")\n    if k == "arith":\n        s = _desc_node(rule["expr"])\n        if s.startswith("(") and s.endswith(")"):\n            s = s[1:-1]\n        if rule.get("round") is not None:\n            s = f"ROUND({s}, {rule[\'round\']})"\n        if rule.get("on_error") is not None:\n            s += f"  (error -> {rule[\'on_error\']})"\n        return s\n    if k == "concat":\n        return " & ".join(f"[{p[\'col\']}]" if "col" in p else f\'"{p["text"]}"\' for p in rule["parts"])\n    if k == "lookup":\n        how = "approximate" if rule.get("approx") else "exact"\n        d = f", default {_fmt_const(rule[\'default\'])}" if rule.get("default") is not None else ""\n        return (f"Lookup {rule[\'table\']}.{rule[\'value\']} where {\', \'.join(rule[\'table_keys\'])} "\n                f"= {\', \'.join(\'[\' + c + \']\' for c in rule[\'keys\'])} ({how}{d})")\n    if k == "cond":\n        return _desc_tree(rule["tree"])\n    if k == "learned_map":\n        return f"Learned mapping from {\', \'.join(\'[\' + c + \']\' for c in rule[\'keys\'])} ({len(rule[\'pairs\'])} entries)"\n    if k == "formula":\n        if rule.get("by_sheet"):\n            return "Formula differs per sheet: " + " | ".join(\n                "%s: %s" % (n, v.get("excel_formula") or v.get("pandas_expr")) for n, v in rule["by_sheet"].items())\n        return rule.get("excel_formula") or rule.get("pandas_expr", "")\n    return k\n\n\n# --------------------------------------------------------------- live Excel formulas\ndef _xl_const(c: Any) -> str:\n    if isinstance(c, str):\n        return \'"\' + c.replace(\'"\', \'""\') + \'"\'\n    if isinstance(c, bool):\n        return "TRUE" if c else "FALSE"\n    return disp(c) if c is not None else \'""\'\n\n\ndef sheet_token(name: str) -> str:\n    """Sheet name as Excel writes it in a formula: quoted only when it has to be."""\n    if re.fullmatch(r"[A-Za-z_][A-Za-z0-9_.]*", name) and not re.fullmatch(r"[A-Za-z]{1,3}\\d+", name):\n        return name\n    return "\'" + name.replace("\'", "\'\'") + "\'"\n\n\ndef excel_formula(rule: Dict[str, Any], ref: Callable[[str], str],\n                  table_ref: Callable[[str, str], str]) -> Optional[str]:\n    """Return an Excel formula for row ``{r}`` or None if this rule can\'t be expressed.\n\n    ``ref(col)`` -> cell reference like ``C{r}``; ``table_ref(table, col)`` -> an absolute\n    column range like ``\'Rates\'!$B:$B``.\n    """\n    k = rule["kind"]\n\n    def node(n):\n        if "col" in n:\n            return ref(n["col"])\n        if "const" in n:\n            return _xl_const(n["const"])\n        if "lookup" in n:\n            return lk(n["lookup"])\n        if "fn" in n:\n            return f"{n[\'fn\'].upper()}({\',\'.join(node(a) for a in n[\'args\'])})"\n        return f"({node(n[\'l\'])}{n[\'op\']}{node(n[\'r\'])})"\n\n    def lk(spec):\n        if len(spec["keys"]) != 1:\n            raise ValueError("multi-key")\n        m = 1 if spec.get("approx") else 0\n        base = (f"INDEX({table_ref(spec[\'table\'], spec[\'value\'])},"\n                f"MATCH({ref(spec[\'keys\'][0])},{table_ref(spec[\'table\'], spec[\'table_keys\'][0])},{m}))")\n        d = spec.get("default")\n        return f"IFERROR({base},{_xl_const(d)})" if d is not None and not spec.get("approx") else base\n\n    def tree(t):\n        if "leaf" in t:\n            return node(t["leaf"])\n        x = t["test"]\n        c = ref(x["col"])\n        v = x.get("value")\n        op = {"==": "=", "!=": "<>"}.get(x["op"], x["op"])\n        if x.get("value_col"):\n            return f"IF({c}{op}{ref(x[\'value_col\'])},{tree(t[\'then\'])},{tree(t[\'else\'])})"\n        if op in ("blank", "is empty"):\n            cond = f\'{c}=""\'\n        elif op in ("not blank", "not empty"):\n            cond = f\'{c}<>""\'\n        elif op in ("in", "not in", "contains", "not contains", "startswith", "endswith"):\n            raise ValueError("op")\n        else:\n            cond = f"{c}{op}{_xl_const(v)}"\n        return f"IF({cond},{tree(t[\'then\'])},{tree(t[\'else\'])})"\n\n    try:\n        if k == "copy":\n            return "=" + ref(rule["col"])\n        if k == "const":\n            return "=" + _xl_const(rule.get("value"))\n        if k == "text":\n            c = ref(rule["col"])\n            f = {"upper": f"UPPER({c})", "lower": f"LOWER({c})", "strip": f"TRIM({c})",\n                 "title": f"PROPER({c})", "left": f"LEFT({c},{rule.get(\'n\')})",\n                 "right": f"RIGHT({c},{rule.get(\'n\')})",\n                 "mid": f"MID({c},{rule.get(\'start\', 1)},{rule.get(\'n\')})", "str": f\'{c}&""\'}[rule["fn"]]\n            return "=" + f\n        if k == "datepart":\n            c = ref(rule["col"])\n            p = rule["part"]\n            f = {"year": f"YEAR({c})", "month": f"MONTH({c})", "day": f"DAY({c})",\n                 "quarter": f"ROUNDUP(MONTH({c})/3,0)", "monthname": f\'TEXT({c},"mmmm")\',\n                 "weekday": f\'TEXT({c},"dddd")\', "ym": f\'TEXT({c},"yyyy-mm")\'}.get(p)\n            return "=" + f if f else None\n        if k == "arith":\n            f = node(rule["expr"])\n            if rule.get("round") is not None:\n                f = f"ROUND({f},{int(rule[\'round\'])})"\n            if rule.get("on_error") is not None:\n                f = f"IFERROR({f},{_xl_const(rule[\'on_error\'])})"\n            return "=" + f\n        if k == "concat":\n            return "=" + "&".join(ref(p["col"]) if "col" in p else _xl_const(p["text"])\n                                  for p in rule["parts"])\n        if k == "lookup":\n            return "=" + lk(rule)\n        if k == "cond":\n            return "=" + tree(rule["tree"])\n        if k == "formula":\n            return None if rule.get("by_sheet") else (rule.get("excel_formula") or None)\n    except (ValueError, KeyError):\n        return None\n    return None\n')

_load('replicator', 'tables', '"""Reading uploaded files into tidy DataFrames and (de)serialising mapping tables."""\n\nfrom __future__ import annotations\n\nimport datetime as dt\nimport io\nimport math\nimport re\nfrom typing import Any, Dict, List, Optional, Tuple\n\nimport numpy as np\nimport openpyxl\nimport pandas as pd\n\nfrom replicator_formulas.sample_parser import detect_header_row, _headers_from_row, _norm, is_toggle_sheet\nfrom .rules import is_blank, nk\n\n\ndef jsonable(v: Any) -> Any:\n    if v is None or v is pd.NaT:\n        return None\n    if isinstance(v, (np.integer,)):\n        return int(v)\n    if isinstance(v, (np.floating, float)):\n        f = float(v)\n        return None if math.isnan(f) or math.isinf(f) else (int(f) if f.is_integer() and abs(f) < 1e15 else f)\n    if isinstance(v, (np.bool_, bool)):\n        return bool(v)\n    if isinstance(v, pd.Timestamp):\n        return v.isoformat()\n    if isinstance(v, (dt.datetime, dt.date)):\n        return v.isoformat()\n    if isinstance(v, dt.time):\n        return v.isoformat()\n    return v if isinstance(v, (int, str)) else str(v)\n\n\ndef _rows_to_df(rows: List[List[Any]]) -> Tuple[pd.DataFrame, int]:\n    rows = [[None if (isinstance(c, float) and math.isnan(c)) else c for c in r] for r in rows]\n    if not any(any(not is_blank(c) for c in r) for r in rows):\n        return pd.DataFrame(), 0\n    hr = detect_header_row(rows)\n    raw_hdr = rows[hr]\n    body = rows[hr + 1:]\n    width = max([len(raw_hdr)] + [len(r) for r in body[:2000]]) if body else len(raw_hdr)\n    raw_hdr = list(raw_hdr) + [None] * (width - len(raw_hdr))\n    keep = [j for j in range(width)\n            if _norm(raw_hdr[j]) or any(j < len(r) and not is_blank(r[j]) for r in body)]\n    headers = _headers_from_row([raw_hdr[j] for j in keep])\n    data = [[(r[j] if j < len(r) else None) for j in keep] for r in body\n            if any(not is_blank(c) for c in r)]\n    df = pd.DataFrame(data, columns=headers, dtype=object)\n    df.attrs["col_offset"] = int(min(keep)) if keep else 0\n    df.attrs["col_idx"] = [int(k) for k in keep]\n    return df, hr\n\n\ndef read_workbook(file_bytes: bytes, filename: str, report: Optional[List[Dict[str, Any]]] = None) -> List[Dict[str, Any]]:\n    """-> [{sheet, header_row, df, n_formulas}] for every non-empty sheet.\n\n    ``report`` (optional list) receives one {sheet, issue} entry per sheet that was skipped or looks wrong."""\n    low = (filename or "").lower()\n    out: List[Dict[str, Any]] = []\n    if low.endswith((".csv", ".txt")):\n        try:\n            raw = pd.read_csv(io.BytesIO(file_bytes), header=None, dtype=object, keep_default_na=False,\n                              skip_blank_lines=False, encoding_errors="replace")\n        except TypeError:                      # pandas < 1.3 has no encoding_errors\n            raw = pd.read_csv(io.BytesIO(file_bytes), header=None, dtype=object, keep_default_na=False,\n                              skip_blank_lines=False, encoding="utf-8")\n        df, hr = _rows_to_df([[None if (isinstance(c, str) and c == "") else c for c in r] for r in raw.values.tolist()])\n        if not df.empty:\n            out.append({"sheet": "Sheet1", "header_row": hr, "df": df, "n_formulas": 0})\n        return out\n    if low.endswith(".xls"):\n        book = pd.read_excel(io.BytesIO(file_bytes), sheet_name=None, header=None,\n                             dtype=object, engine="xlrd")\n        for name, raw in book.items():\n            df, hr = _rows_to_df(raw.values.tolist())\n            if not df.empty:\n                out.append({"sheet": name, "header_row": hr, "df": df, "n_formulas": 0})\n        return out\n    # Read once in streaming mode.  Formulas come back as "=..." strings; only if the workbook has any do\n    # we read it a second time for the saved results (so plain data files are parsed just once).\n    wb_f = openpyxl.load_workbook(io.BytesIO(file_bytes), data_only=False, read_only=True)\n    raw: Dict[str, List[List[Any]]] = {}\n    for ws in wb_f.worksheets:\n        try:\n            ws.reset_dimensions()          # some generators write a wrong <dimension>; recompute it\n        except Exception:  # noqa: BLE001\n            pass\n        raw[ws.title] = [list(r) for r in ws.iter_rows(values_only=True)]\n    wb_f.close()\n\n    def has_formula(rows):\n        return any(isinstance(c, str) and c.startswith("=") for r in rows for c in r)\n    needs_values = {n for n, rows in raw.items() if has_formula(rows)}\n    vals: Dict[str, List[List[Any]]] = {}\n    if needs_values:\n        wb_v = openpyxl.load_workbook(io.BytesIO(file_bytes), data_only=True, read_only=True)\n        for ws in wb_v.worksheets:\n            if ws.title in needs_values:\n                try:\n                    ws.reset_dimensions()\n                except Exception:  # noqa: BLE001\n                    pass\n                vals[ws.title] = [list(r) for r in ws.iter_rows(values_only=True)]\n        wb_v.close()\n    for name, frows in raw.items():\n        nf = unc = 0\n        if name in needs_values:\n            vrows = vals.get(name, [])\n            for fr, vr in zip(frows, vrows):\n                for c, v in zip(fr, vr):\n                    if isinstance(c, str) and c.startswith("="):\n                        nf += 1\n                        unc += v is None\n            rows = vrows\n        else:\n            rows = frows\n        grid = None\n        if is_toggle_sheet(name):            # name|Yes/No rows: keep the grid so cell addresses (B2) stay exact\n            grid = [[jsonable(c) for c in r] for r in rows]\n            while grid and not any(c is not None for c in grid[-1]):\n                grid.pop()\n            if grid and grid[0] and len(grid[0]) > 1 and _yn_like(grid[0][1]):     # no header row at all\n                rows = [["Label", "Value"]] + [list(r[:2]) for r in rows]\n        df, hr = _rows_to_df(rows)\n        if df.empty:\n            if report is not None:\n                report.append({"sheet": name, "issue": (\n                    "skipped: %d formula cell(s) have no saved result, so there are no values to read - open the "\n                    "file in Excel, save it, and upload it again" % nf) if nf else "skipped: the sheet is empty"})\n            continue\n        if unc and report is not None:\n            report.append({"sheet": name, "issue": "%d of %d formula cell(s) have no saved result and read as blank "\n                           "- open the file in Excel and save it, then upload again" % (unc, nf)})\n        fcells: Dict[str, Dict[str, Any]] = {}\n        if name in needs_values:\n            for j, k in enumerate(df.attrs.get("col_idx", [])):\n                for ri in range(hr + 1, len(frows)):\n                    v = frows[ri][k] if k < len(frows[ri]) else None\n                    if isinstance(v, str) and v.startswith("="):\n                        fcells[str(df.columns[j])] = {"raw": v, "row": ri + 1}      # verbatim text, 1-based Excel row\n                        break\n        out.append({"sheet": name, "header_row": hr, "df": df, "n_formulas": nf, "col_offset": df.attrs.get("col_offset", 0),\n                    "col_idx": df.attrs.get("col_idx", []), "formula_cells": fcells, "grid": grid})\n    return out\n\n\ndef _yn_like(v: Any) -> bool:\n    return str(v).strip().lower() in ("yes", "no", "y", "n", "true", "false", "1", "0")\n\n\ndef yes_no(raw: Any) -> Optional[str]:\n    """Toggle cell value -> \'Yes\' / \'No\' (None when it isn\'t a switch value)."""\n    s = str(raw).strip().lower() if raw is not None else ""\n    if s in ("yes", "y", "true", "1"):\n        return "Yes"\n    if s in ("no", "n", "false", "0"):\n        return "No"\n    return None\n\n\ndef guess_role(filename: str, sheet: str, n_formulas: int, is_first: bool) -> str:\n    if re.search(r"dictionary|readme|read_me|notes?\\b|instructions|legend|glossary|about", sheet.lower()):\n        return "ignore"\n    s = f"{filename} {sheet}".lower()\n    if re.search(r"\\b(map|mapping|lookup|rate|rates|ref|reference|master|param|toggle)", s):\n        return "mapping"\n    return "input"\n\n\ndef df_to_spec(df: pd.DataFrame, header_row: int = 0, col_offset: int = 0, grid: Any = None) -> Dict[str, Any]:\n    recs = [{c: jsonable(v) for c, v in zip(df.columns, row)}\n            for row in df.itertuples(index=False, name=None)]\n    return {"headers": [str(c) for c in df.columns], "records": recs, "header_row": int(header_row), "col_offset": int(col_offset),\n            **({"grid": grid} if grid else {})}\n\n\ndef spec_to_df(spec: Dict[str, Any]) -> pd.DataFrame:\n    return pd.DataFrame(spec["records"], columns=spec["headers"], dtype=object)\n\n\ndef summarize(df: pd.DataFrame, n_preview: int = 5) -> Dict[str, Any]:\n    prev = [[jsonable(v) for v in row] for row in df.head(n_preview).itertuples(index=False, name=None)]\n    return {"rows": int(len(df)), "cols": int(df.shape[1]),\n            "headers": [str(c) for c in df.columns], "preview": prev}\n\n\ndef canonical_columns(df: pd.DataFrame, wanted: List[str]) -> pd.DataFrame:\n    """Rename df columns to the stored names (case/space-insensitive)."""\n    low = {nk(c): c for c in wanted}\n    ren, seen = {}, set()\n    for c in df.columns:\n        t = low.get(nk(c))\n        if t and t not in seen:\n            ren[c] = t\n            seen.add(t)\n    return df.rename(columns=ren)\n\n\n_SHEET_REF = re.compile(r"(?:\'((?:[^\']|\'\')+)\'|([A-Za-z_][A-Za-z0-9_.]*))!")\n\n\ndef formula_sheet_refs(file_bytes: bytes, filename: str) -> Dict[str, Any]:\n    """Which sheets hold formulas, and which sheets those formulas point at (mapping sheets)."""\n    if not (filename or "").lower().endswith((".xlsx", ".xlsm")):\n        return {"with_formulas": set(), "referenced": set()}\n    wb = openpyxl.load_workbook(io.BytesIO(file_bytes), data_only=False)\n    withf, refd = set(), set()\n    for ws in wb.worksheets:\n        for row in ws.iter_rows():\n            for c in row:\n                if isinstance(c.value, str) and c.value.startswith("="):\n                    withf.add(ws.title)\n                    for m in _SHEET_REF.finditer(c.value):\n                        refd.add((m.group(1) or m.group(2)).replace("\'\'", "\'"))\n    return {"with_formulas": withf, "referenced": refd - {ws.title for ws in wb.worksheets if ws.title in withf}}\n')

_load('replicator', 'learn', '"""Helpers that work out a sample\'s *row routing*: which input rows each output sheet holds.\n\n``align``      lines the input rows up with a sample output sheet (by row order or by an identifying column)\n``build_tree`` finds a small IF-chain explaining which rows were kept (used for the input filter)\n"""\n\nfrom __future__ import annotations\n\nimport itertools\nimport math\nfrom typing import Any, Dict, List, Optional, Tuple\n\nimport numpy as np\nimport pandas as pd\n\nfrom .rules import eq_series, nk, numeric_share, to_num\n\nSAMPLE = 600\n\n\ndef _unique_ratio(s: pd.Series) -> float:\n    k = s.map(nk)\n    nb = k[k != ""]\n    return float(nb.nunique() / len(k)) if len(k) else 0.0\n\n\ndef align(X: pd.DataFrame, Y: pd.DataFrame) -> Tuple[pd.DataFrame, np.ndarray, Dict[str, Any]]:\n    """Return (X rows matching Y rows in Y\'s order, bool mask of X rows present in Y, info)."""\n    X = X.reset_index(drop=True)\n    Y = Y.reset_index(drop=True)\n    common = [(c, d) for c in X.columns for d in Y.columns if nk(c) == nk(d)]\n    info: Dict[str, Any] = {"input_rows": len(X), "output_rows": len(Y)}\n\n    pos_score = -1.0\n    if len(X) == len(Y):\n        if common:\n            sc = [eq_series(X[c].iloc[:SAMPLE], Y[d].iloc[:SAMPLE]).mean() for c, d in common[:6]]\n            pos_score = float(np.max(sc))\n        else:\n            pos_score = 0.5\n        if pos_score >= 0.97:\n            info.update(method="row order", key=None)\n            return X.copy(), np.ones(len(X), bool), info\n\n    # key join: a (composite of up to 2) column(s) that identify rows on both sides\n    def make_key(df, cols):\n        ks = [df[c].map(nk) for c in cols]\n        k = ks[0]\n        for extra in ks[1:]:\n            k = k + "\\x1f" + extra\n        return k\n\n    options: List[Tuple[float, List[str], List[str]]] = []\n    singles = []\n    for c, d in common or []:\n        singles.append(([c], [d]))\n    if not common:  # different names: compare values\n        for d in Y.columns:\n            if _unique_ratio(Y[d]) < 0.98:\n                continue\n            ys = set(Y[d].map(nk))\n            for c in X.columns:\n                xs = set(X[c].map(nk))\n                if len(ys & xs) >= 0.98 * len(ys):\n                    singles.append(([c], [d]))\n    for xc, yc in singles:\n        yk = make_key(Y, yc)\n        xk = make_key(X, xc)\n        if (yk != "").mean() < 0.98:\n            continue\n        cov = float(yk.isin(set(xk)).mean())\n        uq = float(yk.nunique() / len(yk))\n        if cov >= 0.98 and uq >= 0.98:\n            options.append((cov + uq + 0.01 * (nk(xc[0]) == nk(yc[0])), xc, yc))\n    if not options and len(common) >= 2:\n        for (c1, d1), (c2, d2) in itertools.combinations(common[:8], 2):\n            yk = make_key(Y, [d1, d2])\n            xk = make_key(X, [c1, c2])\n            cov = float(yk.isin(set(xk)).mean())\n            uq = float(yk.nunique() / len(yk))\n            if cov >= 0.98 and uq >= 0.98:\n                options.append((cov + uq, [c1, c2], [d1, d2]))\n    if options:\n        options.sort(key=lambda t: -t[0])\n        _, xc, yc = options[0]\n        xk, yk = make_key(X, xc), make_key(Y, yc)\n        first: Dict[str, int] = {}\n        for i, k in enumerate(xk):\n            first.setdefault(k, i)\n        idx = [first[k] for k in yk if k in first]\n        if len(idx) == len(Y):\n            mask = np.zeros(len(X), bool)\n            mask[list(set(idx))] = True\n            info.update(method="key", key=xc if xc == yc else [f"{a} = {b}" for a, b in zip(xc, yc)])\n            return X.iloc[idx].reset_index(drop=True), mask, info\n    if common:                                  # no ID needed: match whole rows (all shared columns together)\n        xs_cols, ys_cols = [c for c, _ in common], [d for _, d in common]\n        pool: Dict[Tuple, List[int]] = {}\n        for i, sig in enumerate(zip(*[X[c].map(nk) for c in xs_cols])):\n            pool.setdefault(sig, []).append(i)\n        used: Dict[Tuple, int] = {}\n        idx, ok = [], True\n        for sig in zip(*[Y[d].map(nk) for d in ys_cols]):\n            lst = pool.get(sig)\n            if not lst:\n                ok = False\n                break\n            n = used.get(sig, 0)\n            idx.append(lst[min(n, len(lst) - 1)])\n            used[sig] = n + 1\n        if ok and idx:\n            mask = np.zeros(len(X), bool)\n            mask[idx] = True\n            info.update(method="whole rows", key=xs_cols)\n            return X.iloc[idx].reset_index(drop=True), mask, info\n    if len(X) == len(Y):\n        info.update(method="row order", key=None,\n                    warning="No identifying key found; assumed the output is in the same row order.")\n        return X.copy(), np.ones(len(X), bool), info\n    raise ValueError(\n        "Could not line up the input rows with the output rows (%d vs %d). Make sure at least one "\n        "identifying column (an ID / reference) is carried into the output." % (len(X), len(Y)))\n\n\ndef _py(v):\n    if isinstance(v, (np.integer,)):\n        return int(v)\n    if isinstance(v, (np.floating,)):\n        f = float(v)\n        return None if math.isnan(f) else (int(f) if f.is_integer() else f)\n    if isinstance(v, float) and math.isnan(v):\n        return None\n    if v is pd.NaT:\n        return None\n    if isinstance(v, (pd.Timestamp,)):\n        return v.isoformat()\n    return v\n\n\ndef _numfmt(x: float):\n    return int(x) if float(x).is_integer() else x\n\n\ndef _nice_threshold(lo: float, hi: float) -> float:\n    """Roundest number t with lo < t <= hi (so test is `>= t`)."""\n    for k in range(12, -7, -1):\n        step = 10.0 ** k\n        t = math.floor(lo / step + 1e-12) * step + step\n        if t <= hi + 1e-12 and t > lo:\n            return float(round(t, 9))\n    return hi\n\n\ndef build_tree(df: pd.DataFrame, y: pd.Series, max_depth: int = 3, max_leaves: int = 10,\n               feature_cols: Optional[List[str]] = None) -> Optional[Dict[str, Any]]:\n    yk = y.map(nk).values\n    classes = list(dict.fromkeys(yk))\n    if len(classes) < 2 or len(classes) > 12:\n        return None\n    y_orig = {}\n    for k, v in zip(yk, y):\n        y_orig.setdefault(k, _py(v))\n    cls_idx = {c: i for i, c in enumerate(classes)}\n    yi = np.array([cls_idx[k] for k in yk])\n    K = len(classes)\n    cols = feature_cols or list(df.columns)\n    feats = {}\n    for c in cols:\n        s = df[c]\n        if numeric_share(s) >= 0.97:\n            feats[c] = ("num", to_num(s).values.astype(float))\n        else:\n            feats[c] = ("cat", s.map(nk).values)\n    num_cols = [c for c, (k, _) in feats.items() if k == "num"][:12]\n    pairs = [(a, b, op) for a in num_cols for b in num_cols if a != b for op in (">", ">=")]\n    leaves = [0]\n\n    def leaf(idx):\n        cnt = np.bincount(yi[idx], minlength=K)\n        return {"leaf": {"const": y_orig[classes[int(cnt.argmax())]]}}\n\n    def best_split(idx):\n        base = np.bincount(yi[idx], minlength=K).max()\n        best = (base, None)\n        for c, (kind, arr) in feats.items():\n            v = arr[idx]\n            yy = yi[idx]\n            if kind == "num":\n                order = np.argsort(v, kind="stable")\n                vs, ys_ = v[order], yy[order]\n                oh = np.zeros((len(vs), K))\n                oh[np.arange(len(vs)), ys_] = 1\n                cum = np.cumsum(oh, axis=0)\n                tot = cum[-1]\n                for i in range(len(vs) - 1):\n                    if vs[i] == vs[i + 1]:\n                        continue\n                    score = cum[i].max() + (tot - cum[i]).max()\n                    if score > best[0] + 1e-9:\n                        t = _nice_threshold(float(vs[i]), float(vs[i + 1]))\n                        best = (score, {"col": c, "op": ">=", "value": _numfmt(t)})\n            else:\n                for val in np.unique(v):\n                    if val == "":\n                        continue\n                    m = v == val\n                    if m.all():\n                        continue\n                    score = np.bincount(yy[m], minlength=K).max() + np.bincount(yy[~m], minlength=K).max()\n                    if score > best[0] + 1e-9:\n                        orig = next(df[c].iloc[j] for j in idx if arr[j] == val)\n                        best = (score, {"col": c, "op": "==", "value": _py(orig)})\n        for a, b, op in pairs:\n            va, vb = feats[a][1][idx], feats[b][1][idx]\n            m = (va > vb) if op == ">" else (va >= vb)\n            if m.all() or not m.any():\n                continue\n            score = np.bincount(yy_all(idx)[m], minlength=K).max() + np.bincount(yy_all(idx)[~m], minlength=K).max()\n            if score > best[0] + 1e-9:\n                best = (score, {"col": a, "op": op, "value_col": b})\n        return best[1]\n\n    def yy_all(idx):\n        return yi[idx]\n\n    def split_mask(test):\n        if test.get("value_col"):\n            xa, xb = feats[test["col"]][1], feats[test["value_col"]][1]\n            return (xa > xb) if test["op"] == ">" else (xa >= xb)\n        arr_kind, arr = feats[test["col"]]\n        if test["op"] == ">=":\n            return arr >= float(test["value"])\n        return arr == nk(test["value"])\n\n    def rec(idx, depth):\n        if len(set(yi[idx])) == 1 or depth >= max_depth:\n            leaves[0] += 1\n            return leaf(idx)\n        test = best_split(idx)\n        if test is None:\n            leaves[0] += 1\n            return leaf(idx)\n        m = split_mask(test)\n        a, b = idx[m[idx]], idx[~m[idx]]\n        if len(a) == 0 or len(b) == 0:\n            leaves[0] += 1\n            return leaf(idx)\n        return {"test": test, "then": rec(a, depth + 1), "else": rec(b, depth + 1)}\n\n    tree = rec(np.arange(len(df)), 0)\n    if leaves[0] > max_leaves or "leaf" in tree:\n        return None\n    return tree\n')

_load('replicator', 'engine', '"""The whole product, simply: a *template* learned from the sample, replayed on new input.\n\nFor every output sheet of the sample we remember\n  * where it starts (header row, first column) and its column order,\n  * which columns are INPUT columns (pasted from the input rows that pass the sheet\'s filter), and\n  * which columns are DERIVED (header + the sample\'s formula, stored verbatim and filled down),\nplus the sheet filters (editable), the mapping / toggle sheets (copied along) and any parameter cell a formula points at.\n\nNothing is calculated or guessed at run time.  Dataiku-free; the backend only moves bytes in and out of folders.\n"""\n\nfrom __future__ import annotations\n\nimport datetime as dt\nimport io\nimport math\nimport re\nimport uuid\nimport zipfile\nfrom collections import OrderedDict\nfrom typing import Any, Dict, List, Optional, Tuple\n\nimport numpy as np\nimport openpyxl\nimport pandas as pd\nfrom openpyxl.styles import Alignment, Font, PatternFill\nfrom openpyxl.utils import get_column_letter\nfrom xml.sax.saxutils import escape\n\nfrom . import rules as R\nfrom .learn import align, build_tree\nfrom .rules import cmp_mask, disp, is_blank, nk\nfrom replicator_formulas.sample_parser import is_toggle_sheet\nfrom .tables import canonical_columns, df_to_spec, jsonable, spec_to_df, yes_no\n\n\nENGINE_BUILD = "2026.10a"\n\n\nSRC = "Source sheet"\n\n\n_BAD_SHEET = re.compile(r"[\\[\\]:*?/\\\\]")\n\n\ndef conditions_mask(df: pd.DataFrame, conds: List[Dict[str, Any]], match: str = "all") -> pd.Series:\n    if not conds:\n        return pd.Series(True, index=df.index)\n    masks = []\n    for c in conds:\n        col = R.resolve_col(df, c["col"])\n        masks.append(cmp_mask(df[col], c["op"], c.get("value")))\n    m = masks[0]\n    for x in masks[1:]:\n        m = (m & x) if match == "all" else (m | x)\n    return m\n\n\n_INV = {">=": "<", "<": ">=", ">": "<=", "<=": ">", "==": "!=", "!=": "=="}\n\n\ndef _tree_to_conditions(tree: Dict[str, Any], keep: str = "Yes") -> Optional[List[Dict[str, Any]]]:\n    out: List[Dict[str, Any]] = []\n    node = tree\n    while "test" in node:\n        t = dict(node["test"])\n        a, b = node["then"], node["else"]\n\n        def is_leaf(n, val):\n            return "leaf" in n and nk(n["leaf"].get("const")) == nk(val)\n        if is_leaf(b, "No") and not is_leaf(a, "No"):\n            out.append(t)\n            node = a\n        elif is_leaf(a, "No") and not is_leaf(b, "No"):\n            t["op"] = _INV[t["op"]]\n            out.append(t)\n            node = b\n        else:\n            return None\n    return out if is_leaf_yes(node) else None\n\n\ndef is_leaf_yes(node) -> bool:\n    return "leaf" in node and nk(node["leaf"].get("const")) == "yes"\n\n\ndef detect_pre_filter(X: pd.DataFrame, included: np.ndarray) -> Tuple[List[Dict[str, Any]], Optional[str]]:\n    if included.all():\n        return [], None\n    y = pd.Series(np.where(included, "Yes", "No"))\n    tree = build_tree(X.reset_index(drop=True), y, max_depth=3, max_leaves=6)\n    conds = _tree_to_conditions(tree) if tree else None\n    if conds and conditions_mask(X.reset_index(drop=True), conds).eq(included).all():\n        return conds, None\n    return [], ("Some input rows are not in the output but no simple rule explains which; add an "\n                "input filter manually if rows should be dropped.")\n\n\ndef detect_split(work: pd.DataFrame, sheet: pd.Series) -> Tuple[Dict[str, Any], Optional[str]]:\n    sheets = list(dict.fromkeys(sheet))\n    off = {"enabled": False, "mode": "column", "column": "", "map": {}, "new_values": "create",\n           "sheets": [], "rest_sheet": ""}\n    if len(sheets) < 2:\n        return off, None\n    for c in work.columns:\n        if c == "__sheet__":\n            continue\n        keys = work[c].map(nk)\n        modal: Dict[str, str] = {}\n        ok = True\n        for sh in sheets:\n            vc = keys[(sheet == sh).values].value_counts()\n            if vc.empty or vc.iloc[0] < 0.98 * vc.sum() or vc.index[0] == "":\n                ok = False\n                break\n            modal[sh] = vc.index[0]\n        if ok and len(set(modal.values())) == len(sheets):\n            mp = {}\n            for sh in sheets:\n                row = int(np.argmax(((sheet == sh).values) & (keys == modal[sh]).values))\n                mp[str(jsonable(work[c].iloc[row]) if not isinstance(work[c].iloc[row], str)\n                       else work[c].iloc[row])] = sh\n            return {"enabled": True, "mode": "column", "column": c, "map": mp,\n                    "new_values": "create", "sheets": [], "rest_sheet": ""}, None\n    cust = dict(off)\n    cust.update(enabled=True, mode="custom",\n                sheets=[{"name": sh, "match": "all", "conditions": []} for sh in sheets])\n    return cust, ("The output has several sheets but no single column explains the split - define "\n                  "each sheet\'s filter under Filters.")\n\n\ndef _route_conditions(full: pd.DataFrame, mask: np.ndarray, sheet: str) -> Optional[List[Dict[str, Any]]]:\n    best = None\n    for pos, c in enumerate(full.columns):\n        ks = full[c].map(nk)\n        inc, exc = set(ks[mask]), set(ks[~mask])\n        if not inc or "" in inc or inc & exc:\n            continue\n        exact = inc == {nk(sheet)}\n        score = (0 if exact else 1, len(inc), pos)\n        if best is None or score < best[0]:\n            orig = [next(v for v, k in zip(full[c], ks) if k == i) for i in sorted(inc)]\n            cond = {"col": c, "op": "==", "value": jsonable(orig[0])} if len(orig) == 1 else \\\n                {"col": c, "op": "in", "value": [str(jsonable(o)) for o in orig]}\n            best = (score, [cond])\n    if best:\n        return best[1]\n    tree = build_tree(full, pd.Series(np.where(mask, "Yes", "No")), max_depth=3, max_leaves=6)\n    conds = _tree_to_conditions(tree) if tree else None\n    return conds\n\n\ndef _stem(fn: str) -> str:\n    return re.sub(r"\\.[^.]+$", "", fn or "")\n\n\ndef _unique_name(base: str, taken: set) -> str:\n    n, i = base, 2\n    while n in taken:\n        n = f"{base}_{i}"\n        i += 1\n    return n\n\n\n_REF = re.compile(r"(?<![A-Za-z0-9_.])(\\$?)([A-Z]{1,3})(\\$?)(\\d+)(?![\\d(A-Za-z_!])")\n\n\n_LITERALS = re.compile(r"(\\"(?:[^\\"]|\\"\\")*\\"|\'(?:[^\']|\'\')*\')")\n\n\ndef shift_formula(f: str, from_row: int, to_row: int) -> str:\n    """The sample\'s formula text for another row - exactly what Excel does when you fill a formula down:\n    row numbers without a $ move by the row difference; $-anchored refs, ranges, sheet names and text stay."""\n    d = to_row - from_row\n    if d == 0 or not f:\n        return f\n    parts = _LITERALS.split(f)\n    for i in range(0, len(parts), 2):          # odd parts are "text" / \'Sheet name\' literals\n        parts[i] = _REF.sub(lambda m: m.group(0) if m.group(3) == "$" or int(m.group(4)) + d < 1\n                            else "%s%s%s%d" % (m.group(1), m.group(2), m.group(3), int(m.group(4)) + d), parts[i])\n    return "".join(parts)\n\n\ndef _cell_addr(a1: str) -> Tuple[int, int]:\n    m = re.match(r"^\\$?([A-Za-z]{1,3})\\$?(\\d+)$", a1.strip())\n    col = 0\n    for ch in m.group(1).upper():\n        col = col * 26 + ord(ch) - 64\n    return int(m.group(2)) - 1, col - 1\n\n\ndef effective_toggles(system: Dict[str, Any], frames: Optional[Dict[str, pd.DataFrame]] = None,\n                      overrides: Optional[Dict[str, str]] = None) -> List[Dict[str, Any]]:\n    """Toggle values to use *now*: the Toggle sheet of the (stored or freshly attached) mapping wins over the\n    value seen in the example; an explicit per-run override wins over everything."""\n    frames = frames if frames is not None else tables_to_frames(system)\n    out = []\n    for t in system.get("toggles", []):\n        t = dict(t)\n        val = None\n        if t.get("sheet"):\n            tname = next((n for n in frames if nk(n) == nk(t["sheet"])), None)\n            if tname is not None:\n                df = frames[tname]\n                base = re.sub(r"\\s*\\(\\d+\\)$", "", t["name"])\n                if df.shape[1] >= 2:                       # label | value rows\n                    hit = df[df.iloc[:, 0].map(nk).isin([nk(t["name"]), nk(base)])]\n                    if len(hit):\n                        val = yes_no(hit.iloc[0, 1])\n                spec = system.get("tables", {}).get(tname) or {}\n                if val is None and spec.get("grid") and t.get("cell"):    # exact cell of the stored grid\n                    r, c = _cell_addr(t["cell"])\n                    g = spec["grid"]\n                    if r < len(g) and c < len(g[r]):\n                        val = yes_no(g[r][c])\n        if overrides and t["name"] in overrides:\n            val = yes_no(overrides[t["name"]]) or val\n        if val:\n            t["value"] = val\n        out.append(t)\n    return out\n\n\ndef tables_to_frames(system: Dict[str, Any], override: Optional[Dict[str, pd.DataFrame]] = None\n                     ) -> Dict[str, pd.DataFrame]:\n    t = {n: spec_to_df(s) for n, s in system.get("tables", {}).items()}\n    for n, df in (override or {}).items():\n        t[n] = df\n    return t\n\n\ndef prepare_input(system: Dict[str, Any], df: pd.DataFrame) -> Tuple[pd.DataFrame, List[str]]:\n    wanted = system["input"]["columns"]\n    df = canonical_columns(df.reset_index(drop=True), wanted)\n    notes = []\n    if SRC in wanted and SRC not in df.columns:\n        df[SRC] = "Input"\n        notes.append("The input had a single sheet, so no split by input sheet is possible (sheet name \'Input\' used).")\n    have = set(df.columns)\n    missing_req = [c for c in system["input"].get("required", []) if c not in have]\n    if missing_req:\n        raise ValueError("Input is missing required column(s): " + ", ".join(missing_req) +\n                         ". Expected columns: " + ", ".join(wanted))\n    for c in wanted:\n        if c not in have:\n            df[c] = np.nan\n            notes.append(f"Input column \'{c}\' not found - treated as blank.")\n    extra = [c for c in df.columns if c not in set(wanted)]\n    if extra:\n        notes.append("Ignored extra input column(s): " + ", ".join(map(str, extra[:8])))\n    return df, notes\n\n\ndef safe_sheet_name(name: str, taken: set) -> str:\n    base = _BAD_SHEET.sub("-", str(name)).strip().strip("\'") or "Sheet"\n    base = base[:31]\n    n, i = base, 2\n    while n.lower() in {t.lower() for t in taken}:\n        suf = f" ({i})"\n        n = base[:31 - len(suf)] + suf\n        i += 1\n    taken.add(n)\n    return n\n\n\ndef split_frames(system: Dict[str, Any], out: pd.DataFrame, work: pd.DataFrame\n                 ) -> Tuple["OrderedDict[str, pd.DataFrame]", List[str]]:\n    sp = system.get("filters", {}).get("split", {})\n    notes: List[str] = []\n    taken: set = set()\n    res0: "OrderedDict[str, pd.DataFrame]" = OrderedDict()\n    res = res0\n    sc = system["output"].get("sheet_columns") or {}\n    if not sp.get("enabled"):\n        nm = system["output"].get("sheet_name") or "Output"\n        res[safe_sheet_name(nm, taken)] = out[[c for c in sc[nm] if c in out.columns]] if nm in sc else out\n        return res, notes\n    common = [c for c in system["output"]["columns"] if all(c in v for v in sc.values())] if sc else []\n\n    def pick(name: str, df: pd.DataFrame) -> pd.DataFrame:\n        """Each sheet shows its own columns; sheets the system never saw get the shared ones."""\n        cols = sc.get(name) or (common if sc and common else None)\n        return df[[c for c in cols if c in df.columns]] if cols else df\n    if sp.get("mode") == "column":\n        col = R.resolve_col(work, sp["column"])\n        keys = work[col].map(nk)\n        mapping = {nk(k): v for k, v in sp.get("map", {}).items()}\n        sheet_of = []\n        unassigned = 0\n        for v, k in zip(work[col], keys):\n            if k == "":\n                sheet_of.append(None)\n                unassigned += 1\n            elif k in mapping:\n                sheet_of.append(mapping[k])\n            elif sp.get("new_values", "create") == "create":\n                sheet_of.append(disp(v))\n            else:\n                sheet_of.append(None)\n                unassigned += 1\n        s = pd.Series(sheet_of, index=out.index, dtype=object)\n        order = [v for v in dict.fromkeys(mapping.values()) if (s == v).any()] + \\\n                [v for v in dict.fromkeys(x for x in s if x is not None) if v not in set(mapping.values())]\n        for nm in order:\n            res[safe_sheet_name(nm, taken)] = out[(s == nm).values]\n        if unassigned:\n            notes.append(f"{unassigned} row(s) had a blank/unknown \'{sp[\'column\']}\' and were not placed in a split sheet"\n                         + (" (put in \'Unassigned\')." if sp.get("rest_sheet") else "."))\n            if sp.get("rest_sheet"):\n                res[safe_sheet_name(sp["rest_sheet"] or "Unassigned", taken)] = out[s.isna().values]\n        if not res:\n            res[safe_sheet_name("Output", taken)] = out\n        return OrderedDict((k, pick(k, v)) for k, v in res.items()), notes\n    covered = pd.Series(False, index=out.index)\n    for sh in sp.get("sheets", []):\n        m = conditions_mask(work, sh.get("conditions", []), sh.get("match", "all"))\n        covered |= m.values\n        res[safe_sheet_name(sh["name"], taken)] = out[m.values]\n    if sp.get("rest_sheet"):\n        res[safe_sheet_name(sp["rest_sheet"], taken)] = out[~covered.values]\n    elif (~covered).any():\n        notes.append(f"{int((~covered).sum())} row(s) matched no sheet filter and were left out.")\n    if not res:\n        res[safe_sheet_name("Output", taken)] = out\n    return OrderedDict((k, pick(k, v)) for k, v in res.items()), notes\n\n\nHDR_FILL = PatternFill("solid", fgColor="1F3A5F")\n\n\nHDR_FONT = Font(bold=True, color="FFFFFF")\n\n\nHELP_FILL = PatternFill("solid", fgColor="E8EDF3")\n\n\ndef xl_val(v: Any) -> Any:\n    if v is None or v is pd.NaT:\n        return None\n    if isinstance(v, float) and np.isnan(v):\n        return None\n    if isinstance(v, (np.integer,)):\n        return int(v)\n    if isinstance(v, (np.floating,)):\n        return None if np.isnan(v) else float(v)\n    if isinstance(v, np.bool_):\n        return bool(v)\n    if isinstance(v, pd.Timestamp):\n        return v.to_pydatetime()\n    if isinstance(v, str) and v.startswith("="):\n        return "\'" + v\n    return v\n\n\ndef _autosize(ws, header_len: List[int]) -> None:\n    for i, w in enumerate(header_len, start=1):\n        ws.column_dimensions[get_column_letter(i)].width = max(8, min(48, w + 2))\n\n\ndef _like(orig: Any, yn: str) -> Any:\n    """Write a Yes/No switch in the same style the cell had (TRUE/FALSE, true/false, Yes/No, 1/0)."""\n    on = yn == "Yes"\n    if isinstance(orig, bool):\n        return on\n    if isinstance(orig, (int, float)):\n        return 1 if on else 0\n    t = str(orig or "")\n    word = ("TRUE", "FALSE") if t.lower() in ("true", "false") else (("Y", "N") if t.lower() in ("y", "n") else ("Yes", "No"))\n    w = word[0] if on else word[1]\n    return w.upper() if t.isupper() else (w.lower() if t.islower() else w)\n\n\ndef inject_cached(blob: bytes, sheet_names: List[str], cached: Dict[str, Dict[str, Any]]) -> bytes:\n    """openpyxl writes formulas without their results; add them so the file shows numbers in any viewer\n    (Excel recalculates on open anyway)."""\n    import zipfile\n    from xml.sax.saxutils import escape\n    zin = zipfile.ZipFile(io.BytesIO(blob))\n    out = io.BytesIO()\n    with zipfile.ZipFile(out, "w", zipfile.ZIP_DEFLATED) as zout:\n        for item in zin.infolist():\n            data = zin.read(item.filename)\n            m = re.match(r"xl/worksheets/sheet(\\d+)\\.xml$", item.filename)\n            if m and int(m.group(1)) <= len(sheet_names):\n                vals = cached.get(sheet_names[int(m.group(1)) - 1]) or {}\n\n                def fix(mm):\n                    coord, attrs, f = mm.group(1), mm.group(2), mm.group(3)\n                    v = vals.get(coord)\n                    if v is None or (isinstance(v, float) and np.isnan(v)) or isinstance(v, (dt.date, pd.Timestamp)):\n                        return mm.group(0)\n                    attrs = re.sub(r\'\\s+t="[^"]*"\', "", attrs)\n                    if isinstance(v, (bool, np.bool_)):\n                        return \'<c r="%s"%s t="b"><f>%s</f><v>%d</v></c>\' % (coord, attrs, f, int(v))\n                    if isinstance(v, (int, float, np.integer, np.floating)):\n                        return \'<c r="%s"%s><f>%s</f><v>%s</v></c>\' % (coord, attrs, f, repr(float(v)) if not float(v).is_integer() else int(v))\n                    return \'<c r="%s"%s t="str"><f>%s</f><v>%s</v></c>\' % (coord, attrs, f, escape(str(v)))\n                text = re.sub(r\'<c r="([A-Z]+\\d+)"([^>]*)><f>(.*?)</f><v\\s*/?>(?:</v>)?</c>\', fix, data.decode("utf-8"))\n                data = text.encode("utf-8")\n            zout.writestr(item, data)\n    return out.getvalue()\n\n\n# =============================================================== learning the template\n_GENERIC = {"label", "name", "value", "toggle", "toggles", "key", "parameter", "param", "setting", "switch", "flag"}\n_PARAM_REF = re.compile(r"(?<![A-Za-z0-9_.!\'$:])\\$([A-Z]{1,3})\\$(\\d+)(?![\\d:(])")\n_SHEET_REFS = re.compile(r"(?:\'((?:[^\']|\'\')+)\'|([A-Za-z_][A-Za-z0-9_.]*))!")\n\n\ndef toggles_from_tables(tables: Dict[str, Dict[str, Any]]) -> List[Dict[str, Any]]:\n    """Every Yes/No (TRUE/FALSE, 1/0) row of a sheet called Toggle / Toggles... is a switch."""\n    out: List[Dict[str, Any]] = []\n    for name, spec in tables.items():\n        if not is_toggle_sheet(name):\n            continue\n        for ri, row in enumerate(spec.get("grid") or []):\n            if len(row) > 1 and row[0] is not None and str(row[0]).strip().lower() not in _GENERIC and yes_no(row[1]):\n                label, n = str(row[0]).strip(), 2\n                while any(t["name"] == label for t in out):\n                    label = "%s (%d)" % (str(row[0]).strip(), n)\n                    n += 1\n                out.append({"name": label, "value": yes_no(row[1]), "sheet": name, "cell": "B%d" % (ri + 1)})\n    return out\n\n\ndef _param_cells(e: Dict[str, Any], cols: List[Dict[str, Any]], hr: int) -> List[Dict[str, Any]]:\n    """Single cells like $G$1 that a sample formula points at on its own sheet but that are not part of the table."""\n    cells = []\n    idx = [c["col"] for c in cols]\n    for c in cols:\n        if c["kind"] != "formula":\n            continue\n        for m in _PARAM_REF.finditer(re.sub(r\'"(?:[^"]|"")*"\', "", c["raw"])):\n            col = 0\n            for ch in m.group(1):\n                col = col * 26 + ord(ch) - 64\n            col -= 1\n            row = int(m.group(2))\n            inside = (min(idx) <= col <= max(idx)) and row > hr + 1\n            addr = "%s%d" % (m.group(1), row)\n            if not inside and addr not in [x["cell"] for x in cells]:\n                cells.append({"cell": addr, "row": row - 1, "col": col})\n    if cells and e.get("bytes"):\n        try:\n            ws = openpyxl.load_workbook(io.BytesIO(e["bytes"]), data_only=True)[e["sheet"]]\n            for x in cells:\n                x["value"] = jsonable(ws.cell(row=x["row"] + 1, column=x["col"] + 1).value)\n        except Exception:  # noqa: BLE001\n            pass\n    return cells\n\n\ndef route_sheets(X: pd.DataFrame, masks: Dict[str, np.ndarray], parts: List[pd.DataFrame], labels: List[str]\n                 ) -> Tuple[Dict[str, Any], Optional[str]]:\n    """Which input rows does each sample sheet hold?  Expressed as filters on INPUT columns only."""\n    off = {"enabled": False, "mode": "column", "column": "", "map": {}, "new_values": "create", "sheets": [], "rest_sheet": ""}\n    if len(masks) < 2:\n        return off, None\n    vals = [m for m in masks.values() if m is not None]\n    disjoint = len(vals) == len(masks) and not any((a & b).any() for i, a in enumerate(vals) for b in vals[i + 1:])\n    if disjoint:\n        sp, _ = detect_split(pd.concat(parts, ignore_index=True), pd.Series(labels))\n        if sp.get("enabled") and sp.get("mode") == "column":\n            return sp, None\n    sp = dict(off, enabled=True, mode="custom")\n    miss = []\n    for name, m in masks.items():\n        conds: Optional[List[Dict[str, Any]]] = [] if (m is None or m.all()) else _route_conditions(X, m, name)\n        if conds is None:\n            miss.append(name)\n            conds = []\n        sp["sheets"].append({"name": name, "match": "all", "conditions": conds})\n    return sp, (("Could not work out which rows belong on sheet(s) " + ", ".join(miss) +\n                 " - set their filters under Filters & outputs.") if miss else None)\n\n\ndef build_system(entries: List[Dict[str, Any]], options: Dict[str, Any]) -> Dict[str, Any]:\n    """``entries``: [{file, sheet, role, df, header_row, col_offset, col_idx, formula_cells, grid, bytes}]."""\n    warnings: List[str] = []\n    ins = [e for e in entries if e["role"] == "input"]\n    maps = [e for e in entries if e["role"] == "mapping"]\n    outs = [e for e in entries if e["role"] == "output"]\n    if not ins:\n        raise ValueError("Add at least one input sheet.")\n    if not outs:\n        raise ValueError("Add the expected output sheet(s).")\n\n    # ---- the input: sheets with the same columns are stacked; the biggest stack is the data\n    groups: List[List[Dict[str, Any]]] = []\n    for e in ins:\n        for g in groups:\n            if [nk(c) for c in g[0]["df"].columns] == [nk(c) for c in e["df"].columns]:\n                g.append(e)\n                break\n        else:\n            groups.append([e])\n    groups.sort(key=lambda g: -sum(len(x["df"]) for x in g))\n    primary = groups[0]\n    names = [e["sheet"] for e in primary]\n    parts = []\n    for e in primary:\n        f = canonical_columns(e["df"], list(primary[0]["df"].columns)).copy()\n        if len(primary) > 1:      # the input\'s own sheets are a split: remember which sheet a row came from\n            f[SRC] = e["sheet"] if names.count(e["sheet"]) == 1 else "%s/%s" % (_stem(e["file"]), e["sheet"])\n        parts.append(f)\n    X = pd.concat(parts, ignore_index=True)\n    if len(groups) > 1:\n        warnings.append("Input sheets with a different layout were kept as reference tables: "\n                        + ", ".join(x["sheet"] for g in groups[1:] for x in g))\n\n    # ---- mapping / toggle sheets (uploaded ones win over copies inside the output workbook)\n    out_files = {o["file"] for o in outs}\n    tables: Dict[str, Dict[str, Any]] = {}\n    table_src: Dict[str, str] = {}\n    taken: set = set()\n    for e in sorted(maps, key=lambda e: e["file"] in out_files) + [x for g in groups[1:] for x in g]:\n        dup = next((t for t in tables if nk(t) == nk(e["sheet"])), None)\n        if e["file"] in out_files and dup:\n            if tables[dup]["headers"] != [str(c) for c in e["df"].columns] or len(tables[dup]["records"]) != len(e["df"]):\n                warnings.append(f"Mapping \'{e[\'sheet\']}\' in the output file differs from the uploaded mapping; "\n                                "the uploaded mapping is used.")\n            continue\n        nm = _unique_name(e["sheet"] if e["sheet"] not in taken else f"{_stem(e[\'file\'])}_{e[\'sheet\']}", taken)\n        taken.add(nm)\n        tables[nm] = df_to_spec(e["df"], e.get("header_row", 0), e.get("col_offset", 0), e.get("grid"))\n        table_src[nm] = f"{e[\'file\']} / {e[\'sheet\']}"\n\n    # ---- one template per output sheet\n    in_names = {nk(c): str(c) for c in X.columns if c != SRC}\n    sheets: List[Dict[str, Any]] = []\n    masks: Dict[str, np.ndarray] = {}\n    xs_parts: List[pd.DataFrame] = []\n    labels: List[str] = []\n    for e in outs:\n        df = e["df"]\n        fc = e.get("formula_cells") or {}\n        idx = e.get("col_idx") or list(range(e.get("col_offset", 0), e.get("col_offset", 0) + df.shape[1]))\n        cols: List[Dict[str, Any]] = []\n        for j, c in enumerate(df.columns):\n            st = _sample_type(df.iloc[:, j])\n            c = str(c)\n            if c in fc:\n                cols.append({"name": c, "col": int(idx[j]), "kind": "formula", "raw": fc[c]["raw"], "sample_row": int(fc[c]["row"]), "sample_type": st})\n            elif nk(c) in in_names:\n                cols.append({"name": c, "col": int(idx[j]), "kind": "input", "source": in_names[nk(c)], "sample_type": st})\n            else:\n                cols.append({"name": c, "col": int(idx[j]), "kind": "empty", "sample_type": st})\n        empty = [c["name"] for c in cols if c["kind"] == "empty"]\n        if empty:\n            warnings.append(f"Sheet \'{e[\'sheet\']}\': no formula in the sample for {\', \'.join(empty)} - these columns stay empty.")\n        hr = int(e.get("header_row", 0))\n        in_cols = [c["name"] for c in cols if c["kind"] == "input"]\n        try:\n            if not in_cols:\n                raise ValueError("none of its columns match a column of the input")\n            Xs, m, _ = align(X, df[in_cols])\n            masks[e["sheet"]] = m\n            xs_parts.append(Xs)\n            labels += [e["sheet"]] * len(Xs)\n        except ValueError as exc:\n            masks[e["sheet"]] = None            # unknown: the sheet gets every input row until its filter is set\n            why = str(exc) if not in_cols else f"{len(X)} input rows vs {len(df)} rows in the sample; no identifying column to match them"\n            warnings.append(f"Sheet \'{e[\'sheet\']}\': could not tell which input rows it holds ({why}). It will receive "\n                            "every input row - set its filter under Filters & outputs.")\n        sheets.append({"name": e["sheet"], "origin": {"row": hr, "col": int(min(c["col"] for c in cols))},\n                       "columns": cols, "params": _param_cells(e, cols, hr), "sample_rows": int(len(df))})\n\n    # ---- filters: the input filter + which rows each sheet holds (the user can edit both)\n    flt: Dict[str, Any] = {"pre": [], "split": {"enabled": False, "mode": "column", "column": "", "map": {},\n                                                "new_values": "create", "sheets": [], "rest_sheet": ""}}\n    known = [m for m in masks.values() if m is not None]\n    if len(known) == len(masks):\n        included = np.zeros(len(X), bool)\n        for m in known:\n            included |= m\n        pre, pre_warn = detect_pre_filter(X, included)\n        flt["pre"] = pre\n        if pre_warn:\n            warnings.append(pre_warn)\n    sp_opt = options.get("split") or {}\n    mode = sp_opt.get("mode", "auto")\n    if mode == "none":\n        pass\n    elif mode == "column" and sp_opt.get("column"):\n        col = sp_opt["column"]\n        vals = list(dict.fromkeys(X[col].map(lambda v: v if isinstance(v, str) else jsonable(v))))\n        flt["split"].update(enabled=True, mode="column", column=col, map={str(v): disp(v) for v in vals if not is_blank(v)})\n    elif mode == "custom":\n        flt["split"].update(enabled=True, mode="custom", sheets=sp_opt.get("sheets", []))\n    else:\n        sp, sw = route_sheets(X, masks, xs_parts, labels)\n        flt["split"] = sp\n        if sw:\n            warnings.append(sw)\n\n    system = {\n        "engine": ENGINE_BUILD,\n        "id": options.get("id") or uuid.uuid4().hex[:10],\n        "name": options.get("name") or "Untitled system",\n        "description": options.get("description", ""),\n        "created": dt.datetime.utcnow().isoformat(timespec="seconds") + "Z",\n        "input": {"columns": [str(c) for c in X.columns], "sources": [{"file": e["file"], "sheet": e["sheet"], "rows": int(len(e["df"]))} for e in primary]},\n        "tables": tables, "table_sources": table_src, "toggles": toggles_from_tables(tables),\n        "output": {"sheet_name": outs[0]["sheet"],\n                   "extra_tables": [e["sheet"] for e in maps if e["file"] in out_files]},\n        "sheets": sheets, "filters": flt, "warnings": warnings,\n    }\n    finalize_system(system)\n    return system\n\n\ndef finalize_system(system: Dict[str, Any]) -> None:\n    """Input columns the filters need (a new input must have them); everything else is pasted if present."""\n    incols = {nk(c): c for c in system["input"]["columns"]}\n    required: List[str] = []\n\n    def need(c):\n        if c and nk(c) in incols and incols[nk(c)] not in required:\n            required.append(incols[nk(c)])\n    f = system.get("filters", {})\n    for c in f.get("pre", []):\n        need(c["col"])\n    sp = f.get("split", {})\n    if sp.get("enabled"):\n        if sp.get("mode") == "column":\n            need(sp.get("column"))\n        for s in sp.get("sheets", []):\n            for c in s.get("conditions", []):\n                need(c["col"])\n    system["input"]["required"] = required\n\n\n# =============================================================== editing stored formulas\ndef check_formula(text: str) -> Optional[str]:\n    """Light sanity check (the app never evaluates formulas): looks like a formula, quotes and brackets balance."""\n    t = (text or "").strip()\n    if not t.startswith("="):\n        return "a formula must start with ="\n    if len(t) < 2:\n        return "the formula is empty"\n    if "\\n" in t or "\\r" in t:\n        return "use a single line"\n    depth, in_q, in_s = 0, False, False\n    for ch in t:\n        if ch == \'"\' and not in_s:\n            in_q = not in_q\n        elif ch == "\'" and not in_q:\n            in_s = not in_s\n        elif not in_q and not in_s:\n            if ch == "(":\n                depth += 1\n            elif ch == ")":\n                depth -= 1\n                if depth < 0:\n                    return "a ) has no matching ("\n    if in_q:\n        return \'a " quote is not closed\'\n    if in_s:\n        return "a \' quote is not closed"\n    if depth:\n        return "%d ( not closed" % depth\n    return None\n\n\ndef apply_formula_edits(system: Dict[str, Any], edits: List[Dict[str, Any]]) -> int:\n    """edits: [{sheet, column, raw}] - ``raw`` is the formula as typed for the column\'s first data row.\n    An empty ``raw`` clears the formula.  The original text is remembered (``orig``) so it can be reset."""\n    by = {d["name"]: d for d in system["sheets"]}\n    errors: List[str] = []\n    plan = []\n    for e in edits:\n        d = by.get(e.get("sheet"))\n        c = next((x for x in d["columns"] if x["name"] == e.get("column")), None) if d else None\n        if c is None:\n            errors.append("%s / %s: no such column" % (e.get("sheet"), e.get("column")))\n            continue\n        if c["kind"] == "input":\n            errors.append("%s / %s: this is an input column, not a formula column" % (d["name"], c["name"]))\n            continue\n        raw = (e.get("raw") or "").strip()\n        if raw:\n            err = check_formula(raw)\n            if err:\n                errors.append("%s / %s: %s" % (d["name"], c["name"], err))\n                continue\n        plan.append((d, c, raw))\n    if errors:\n        raise ValueError("; ".join(errors[:5]) + (" ..." if len(errors) > 5 else ""))\n    n = 0\n    for d, c, raw in plan:\n        before = c.get("raw", "")\n        if raw == before:\n            continue\n        c.setdefault("orig", before)\n        if raw:\n            if c["kind"] != "formula":\n                c["kind"] = "formula"\n                c["sample_row"] = d["origin"]["row"] + 2          # typed for the first data row\n            c["raw"] = raw\n        else:\n            c["kind"] = "empty"\n            c.pop("raw", None)\n            c.pop("sample_row", None)\n        if c.get("orig") == c.get("raw", ""):                      # back to the original: nothing is "edited"\n            c.pop("orig", None)\n        n += 1\n    return n\n\n\n# ================================================================== locked data types\nDTYPES = ("auto", "text", "integer", "decimal", "date")\n_EXCEL_EPOCH = dt.datetime(1899, 12, 30)\n_DATE_FMT = re.compile(r"^[A-Za-z0-9 /\\-\\.:,]{1,30}$")\n_TYPE_LABEL = {"text": "text", "integer": "a whole number", "decimal": "a decimal number", "date": "a date"}\n\n\ndef _to_float(v: Any) -> Optional[float]:\n    if isinstance(v, bool):\n        return None\n    if isinstance(v, (int, float, np.integer, np.floating)):\n        x = float(v)\n    else:\n        try:\n            x = float(str(v).strip().replace(",", "").replace(" ", ""))\n        except ValueError:\n            return None\n    return x if math.isfinite(x) else None\n\n\ndef _to_date(v: Any, dayfirst: bool = False) -> Optional[dt.datetime]:\n    if isinstance(v, pd.Timestamp):\n        return None if pd.isna(v) else v.to_pydatetime()\n    if isinstance(v, dt.datetime):\n        return v\n    if isinstance(v, dt.date):\n        return dt.datetime(v.year, v.month, v.day)\n    x = _to_float(v) if not isinstance(v, str) else None\n    if x is not None:                                   # an Excel serial number (1954 .. 2118)\n        return _EXCEL_EPOCH + dt.timedelta(days=x) if 20000 < x < 80000 else None\n    t = pd.to_datetime(str(v).strip(), errors="coerce", dayfirst=dayfirst)\n    return None if pd.isna(t) else t.to_pydatetime()\n\n\ndef coerce_value(v: Any, spec: Dict[str, Any]) -> Tuple[Any, bool]:\n    """Force one value into the locked type -> (value, ok).  Blank stays blank; unreadable -> (None, False)."""\n    if is_blank(v):\n        return None, True\n    t = spec["type"]\n    if t == "text":\n        return disp(v), True\n    if t == "date":\n        d = _to_date(v, bool(spec.get("dayfirst")))\n        return (d, True) if d is not None else (None, False)\n    x = _to_float(v)\n    if x is None:\n        return None, False\n    if t == "integer":\n        return int(math.copysign(math.floor(abs(x) + 0.5), x)), True\n    f = 10.0 ** int(spec.get("decimals", 2))\n    return float(math.copysign(math.floor(round(abs(x) * f, 6) + 0.5), x) / f), True\n\n\ndef number_format_for(spec: Optional[Dict[str, Any]], kind: str) -> Optional[str]:\n    """Excel number format of a locked column (a formula cell is never turned into text)."""\n    if not spec:\n        return None\n    t = spec["type"]\n    if t == "text":\n        return "@" if kind != "formula" else None\n    if t == "integer":\n        return "0"\n    if t == "decimal":\n        d = int(spec.get("decimals", 2))\n        return "0" + ("." + "0" * d if d else "")\n    if t == "date":\n        return spec.get("format") or "yyyy-mm-dd"\n    return None\n\n\ndef _sample_type(series: pd.Series) -> str:\n    vals = [v for v in series if not is_blank(v)]\n    if not vals:\n        return ""\n    if all(isinstance(v, (dt.datetime, dt.date, pd.Timestamp)) for v in vals):\n        return "date"\n    if all(isinstance(v, (int, float, np.integer, np.floating)) and not isinstance(v, bool) for v in vals):\n        return "integer" if all(float(v).is_integer() for v in vals) else "decimal"\n    return "text"\n\n\ndef apply_dtype_edits(system: Dict[str, Any], edits: List[Dict[str, Any]]) -> int:\n    """edits: [{sheet, column, type, decimals?, format?}] - \'auto\' removes the lock."""\n    by = {d["name"]: d for d in system["sheets"]}\n    errors, plan = [], []\n    for e in edits:\n        d = by.get(e.get("sheet"))\n        c = next((x for x in d["columns"] if x["name"] == e.get("column")), None) if d else None\n        t = e.get("type", "auto")\n        if c is None:\n            errors.append("%s / %s: no such column" % (e.get("sheet"), e.get("column")))\n        elif t not in DTYPES:\n            errors.append("%s / %s: unknown type \'%s\' (use %s)" % (d["name"], c["name"], t, ", ".join(DTYPES)))\n        else:\n            spec: Optional[Dict[str, Any]] = None\n            if t != "auto":\n                spec = {"type": t}\n                if t == "decimal":\n                    try:\n                        spec["decimals"] = int(e.get("decimals", 2))\n                        assert 0 <= spec["decimals"] <= 10\n                    except (TypeError, ValueError, AssertionError):\n                        errors.append("%s / %s: decimals must be a whole number from 0 to 10" % (d["name"], c["name"]))\n                        continue\n                if t == "date":\n                    f = (e.get("format") or "yyyy-mm-dd").strip()\n                    if not _DATE_FMT.match(f):\n                        errors.append("%s / %s: date format may only use letters, digits and - / . : , space" % (d["name"], c["name"]))\n                        continue\n                    spec["format"] = f\n                    if e.get("dayfirst"):\n                        spec["dayfirst"] = True          # 04/05/2026 means 4 May, not April 5\n            plan.append((c, spec))\n    if errors:\n        raise ValueError("; ".join(errors[:5]) + (" ..." if len(errors) > 5 else ""))\n    for c, spec in plan:\n        if spec:\n            c["dtype"] = spec\n        else:\n            c.pop("dtype", None)\n    return len(plan)\n\n\n# ======================================================================= applying it\ndef _sheet_frame(d: Dict[str, Any], rows: pd.DataFrame) -> Tuple[pd.DataFrame, List[str]]:\n    """The sheet as it will be written: pasted input values (forced into any locked type) + the sample\'s formulas\n    filled down (nothing else).  Also returns what could not be read as the locked type."""\n    first = d["origin"]["row"] + 2\n    data: "OrderedDict[str, List[Any]]" = OrderedDict()\n    n = len(rows)\n    issues: List[str] = []\n    for c in d["columns"]:\n        if c["kind"] == "input":\n            vals = list(rows[c["source"]]) if c["source"] in rows.columns else [None] * n\n            if c.get("dtype"):\n                out, bad = [], []\n                for v in vals:\n                    x, ok = coerce_value(v, c["dtype"])\n                    out.append(x)\n                    if not ok:\n                        bad.append(v)\n                vals = out\n                if bad:\n                    issues.append("Sheet \'%s\', column \'%s\': %d value(s) could not be read as %s and were left empty (e.g. %s)."\n                                  % (d["name"], c["name"], len(bad), _TYPE_LABEL[c["dtype"]["type"]], ", ".join(map(lambda x: repr(disp(x)), bad[:3]))))\n            data[c["name"]] = vals\n        elif c["kind"] == "formula":\n            data[c["name"]] = [shift_formula(c["raw"], c["sample_row"], first + i) for i in range(n)]\n        else:\n            data[c["name"]] = [None] * n\n    return pd.DataFrame(data, columns=[c["name"] for c in d["columns"]], dtype=object), issues\n\n\ndef apply_system(system: Dict[str, Any], df_in: pd.DataFrame,\n                 table_override: Optional[Dict[str, pd.DataFrame]] = None,\n                 toggle_override: Optional[Dict[str, str]] = None) -> Dict[str, Any]:\n    df, notes = prepare_input(system, df_in)\n    n_in = len(df)\n    pre = system.get("filters", {}).get("pre", [])\n    if pre:\n        df = df[conditions_mask(df, pre).values].reset_index(drop=True)\n        notes.append(f"Input filter kept {len(df)} of {n_in} rows.")\n    frames = tables_to_frames(system, table_override)\n    toggles_now = effective_toggles(system, frames, toggle_override)\n    rows, snotes = split_frames(system, df, df)\n    notes += snotes\n    defs = {s["name"]: s for s in system["sheets"]}\n    sheets: "OrderedDict[str, Dict[str, Any]]" = OrderedDict()\n    for name, rdf in rows.items():\n        d = defs.get(name)\n        if d is None:\n            d = system["sheets"][0]\n            notes.append(f"Sheet \'{name}\' is new: laid out like \'{d[\'name\']}\'.")\n        fr, issues = _sheet_frame(d, rdf.reset_index(drop=True))\n        notes += issues\n        sheets[name] = {"df": fr, "def": d}\n    return {"sheets": sheets, "notes": notes, "toggles": toggles_now, "input_rows": n_in,\n            "rows": int(sum(len(v["df"]) for v in sheets.values()))}\n\n\n# ================================================================ the output workbook\ndef _write_tables(wb, system, tables, toggles, table_sheet):\n    for t, sn in table_sheet.items():\n        ws = wb.create_sheet(sn)\n        T = tables[t]\n        spec = system.get("tables", {}).get(t, {})\n        if spec.get("grid"):                          # Toggle sheet: exact cell layout, current switch values\n            grid = [list(r) for r in spec["grid"]]\n            for tg in toggles:\n                if tg.get("cell") and nk(tg.get("sheet", "")) == nk(t) and tg.get("value"):\n                    r, c = _cell_addr(tg["cell"])\n                    if r < len(grid) and c < len(grid[r]):\n                        grid[r][c] = _like(grid[r][c], tg["value"])\n            for row in grid:\n                ws.append([xl_val(v) for v in row])\n            continue\n        pad = [None] * int(spec.get("col_offset", 0))\n        for _ in range(int(spec.get("header_row", 0))):\n            ws.append([])\n        hr = int(spec.get("header_row", 0)) + 1\n        ws.append(pad + [str(c) for c in T.columns])\n        for row in T.itertuples(index=False, name=None):\n            ws.append(pad + [xl_val(v) for v in row])\n        for j in range(len(pad) + 1, len(pad) + T.shape[1] + 1):\n            ws.cell(row=hr, column=j).font = Font(bold=True)\n\n\ndef write_workbook(system: Dict[str, Any], sheets: "OrderedDict[str, Dict[str, Any]]",\n                   summary: Optional[List[Tuple[str, Any]]] = None,\n                   tables: Optional[Dict[str, pd.DataFrame]] = None,\n                   toggles: Optional[List[Dict[str, Any]]] = None) -> bytes:\n    wb = openpyxl.Workbook()\n    wb.remove(wb.active)\n    tables = tables if tables is not None else tables_to_frames(system)\n    toggles = toggles if toggles is not None else system.get("toggles", [])\n    for sname, item in sheets.items():\n        df, d = item["df"], item["def"]\n        ws = wb.create_sheet(sname)\n        hr = int(d["origin"]["row"])\n        for c, name in zip(d["columns"], df.columns):          # same cells as the sample\n            cell = ws.cell(row=hr + 1, column=c["col"] + 1, value=name)\n            cell.font = HDR_FONT\n            cell.fill = HDR_FILL if c["kind"] != "formula" else PatternFill("solid", fgColor="2F6B4F")\n            cell.alignment = Alignment(vertical="center", wrap_text=True)\n            ws.column_dimensions[get_column_letter(c["col"] + 1)].width = max(9, min(40, len(str(name)) + 3))\n        for ri, row in enumerate(df.itertuples(index=False, name=None), start=hr + 2):\n            for c, v in zip(d["columns"], row):\n                if v is not None and not (isinstance(v, float) and np.isnan(v)):\n                    # a formula is written as a formula; pasted input text starting with "=" stays text\n                    cell = ws.cell(row=ri, column=c["col"] + 1, value=v if c["kind"] == "formula" else xl_val(v))\n                    fmt = number_format_for(c.get("dtype"), c["kind"])\n                    if fmt:                                            # the locked type of this column\n                        cell.number_format = fmt\n        for p in d.get("params", []):                          # parameter cell(s) the formulas point at ($G$1 ...)\n            if p.get("value") is not None:\n                ws.cell(row=p["row"] + 1, column=p["col"] + 1, value=xl_val(p["value"]))\n        ws.freeze_panes = ws.cell(row=hr + 2, column=1).coordinate\n\n    # mapping and toggle sheets are dependencies of the formulas: always part of the output workbook\n    taken = set(sheets.keys()) | {"Run summary"}\n    dependent: List[str] = list(tables)                 # every mapping + toggle sheet of the system comes along\n    dependent += [tg["sheet"] for tg in toggles if tg.get("sheet")]\n    for s in system["sheets"]:\n        for c in s["columns"]:\n            if c["kind"] == "formula":\n                dependent += [(m.group(1) or m.group(2)).replace("\'\'", "\'") for m in _SHEET_REFS.finditer(c["raw"])]\n    table_sheet: Dict[str, str] = {}\n    for t in dict.fromkeys(dependent):\n        t = next((n for n in tables if nk(n) == nk(t)), None)\n        if t is not None and t not in table_sheet:\n            table_sheet[t] = safe_sheet_name(t, taken)\n    _write_tables(wb, system, tables, toggles, table_sheet)\n\n    sm = wb.create_sheet("Run summary")\n    sm.append(["System", system["name"]])\n    sm.append(["Generated", dt.datetime.now().strftime("%Y-%m-%d %H:%M")])\n    sm.append([])\n    sm.append(["Sheet", "Rows"])\n    for c in sm[4]:\n        c.font = Font(bold=True)\n    for sname, item in sheets.items():\n        sm.append([sname, int(len(item["df"]))])\n    if summary:\n        sm.append([])\n        for k, v in summary:\n            sm.append([k, v if not isinstance(v, (list, dict)) else "; ".join(map(str, v))])\n    sm.column_dimensions["A"].width = 30\n    sm.column_dimensions["B"].width = 90\n    buf = io.BytesIO()\n    wb.save(buf)\n    return buf.getvalue()\n')

_load('replicator', 'store', '"""Persistence: a Dataiku managed folder (production) or a local directory (dev / tests).\n\nFolder id comes from, in order: the ``REPLICATOR_FOLDER`` project variable, the env var of the\nsame name, or the ``FOLDER_FALLBACK`` constant below.  Without Dataiku, everything lives under\n``$REPLICATOR_LOCAL_ROOT`` (default ``./_replicator_data``).\n"""\n\nfrom __future__ import annotations\n\nimport io\nimport json\nimport os\nfrom typing import Any, List, Optional\n\nFOLDER_FALLBACK = ""  # hard-wire a managed folder id here if you prefer\n\ntry:  # pragma: no cover - only inside Dataiku\n    import dataiku\n    _HAS_DATAIKU = True\nexcept Exception:  # noqa: BLE001\n    dataiku = None\n    _HAS_DATAIKU = False\n\n\nclass LocalStore:\n    def __init__(self, root: str):\n        self.root = os.path.abspath(root)\n        os.makedirs(self.root, exist_ok=True)\n\n    def _p(self, path: str) -> str:\n        full = os.path.abspath(os.path.join(self.root, path.lstrip("/")))\n        if not full.startswith(self.root):\n            raise ValueError("bad path")\n        return full\n\n    def get(self, path: str) -> Optional[bytes]:\n        try:\n            with open(self._p(path), "rb") as fh:\n                return fh.read()\n        except FileNotFoundError:\n            return None\n\n    def put(self, path: str, data: bytes) -> None:\n        full = self._p(path)\n        os.makedirs(os.path.dirname(full), exist_ok=True)\n        with open(full, "wb") as fh:\n            fh.write(data)\n\n    def list(self, prefix: str = "") -> List[str]:\n        out = []\n        for base, _, files in os.walk(self.root):\n            for f in files:\n                rel = "/" + os.path.relpath(os.path.join(base, f), self.root).replace("\\\\", "/")\n                if rel.startswith("/" + prefix.lstrip("/")):\n                    out.append(rel)\n        return sorted(out)\n\n    def delete(self, path: str) -> None:\n        try:\n            os.remove(self._p(path))\n        except FileNotFoundError:\n            pass\n\n\nclass DataikuStore:  # pragma: no cover - only inside Dataiku\n    def __init__(self, folder_id: str):\n        self.f = dataiku.Folder(folder_id)\n\n    def get(self, path: str) -> Optional[bytes]:\n        try:\n            with self.f.get_download_stream("/" + path.lstrip("/")) as s:\n                return s.read()\n        except Exception:  # noqa: BLE001\n            return None\n\n    def put(self, path: str, data: bytes) -> None:\n        self.f.upload_stream("/" + path.lstrip("/"), io.BytesIO(data))\n\n    def list(self, prefix: str = "") -> List[str]:\n        return sorted(p for p in self.f.list_paths_in_partition() if p.startswith("/" + prefix.lstrip("/")))\n\n    def delete(self, path: str) -> None:\n        try:\n            self.f.delete_path("/" + path.lstrip("/"))\n        except Exception:  # noqa: BLE001\n            pass\n\n\ndef _folder_id(preset: str = "") -> str:\n    if preset:\n        return preset\n    fid = os.environ.get("REPLICATOR_FOLDER", "")\n    if _HAS_DATAIKU:\n        try:\n            fid = dataiku.get_custom_variables().get("REPLICATOR_FOLDER") or fid\n        except Exception:  # noqa: BLE001\n            pass\n    return fid or FOLDER_FALLBACK\n\n\ndef make_store(folder: str = "") -> Any:\n    fid = _folder_id(folder)\n    if _HAS_DATAIKU and fid:\n        return DataikuStore(fid)\n    return LocalStore(os.environ.get("REPLICATOR_LOCAL_ROOT", "_replicator_data"))\n\n\ndef put_json(store: Any, path: str, obj: Any, indent: Optional[int] = None) -> None:\n    store.put(path, json.dumps(obj, ensure_ascii=False, default=str, indent=indent).encode("utf-8"))\n\n\ndef get_json(store: Any, path: str) -> Optional[Any]:\n    raw = store.get(path)\n    return json.loads(raw.decode("utf-8")) if raw else None\n\n\ndef delete_prefix(store: Any, prefix: str) -> None:\n    for p in store.list(prefix):\n        store.delete(p)\n')

_load('replicator', 'service', '"""Application services on top of a store: drafts, systems, runs.  No Flask, no Dataiku."""\n\nfrom __future__ import annotations\n\nimport datetime as dt\nimport io\nimport threading\nimport re\nimport uuid\nfrom typing import Any, Dict, List, Optional, Tuple\n\nimport pandas as pd\n\nfrom . import engine\nfrom .rules import nk\nfrom .store import delete_prefix, get_json, put_json\nfrom .tables import formula_sheet_refs, guess_role, jsonable, read_workbook, summarize, canonical_columns\n\n_DRAFT_LOCK = threading.RLock()   # serialises the draft record update (uploads can overlap)\nALLOWED = (".xlsx", ".xlsm", ".xls", ".csv", ".txt")\nROLES = ("input", "mapping", "output", "ignore")\n\n\ndef _now() -> str:\n    return dt.datetime.utcnow().isoformat(timespec="seconds") + "Z"\n\n\ndef _slug(s: str) -> str:\n    return re.sub(r"[^A-Za-z0-9._-]+", "_", s)[:60] or "file"\n\n\n# ====================================================================== drafts\ndef new_draft(store) -> str:\n    did = uuid.uuid4().hex[:10]\n    put_json(store, f"drafts/{did}/draft.json", {"id": did, "created": _now(), "files": []})\n    return did\n\n\ndef get_draft(store, did: str) -> Dict[str, Any]:\n    d = get_json(store, f"drafts/{did}/draft.json")\n    if d is None:\n        raise KeyError("draft not found")\n    return d\n\n\ndef add_draft_files(store, did: str, files: List[Tuple[str, bytes]], hint: str = "") -> Dict[str, Any]:\n    get_draft(store, did)                      # fail early if the draft is unknown\n    entries = []\n    for name, data in files:                   # slow part (parsing) runs outside the lock\n        if not name.lower().endswith(ALLOWED):\n            raise ValueError(f"{name}: unsupported file type (use .xlsx, .xls or .csv)")\n        report: List[Dict[str, Any]] = []\n        sheets = read_workbook(data, name, report)\n        if not sheets:\n            why = "; ".join("%s %s" % (r["sheet"], r["issue"]) for r in report)\n            raise ValueError(f"{name}: no data found" + (f" ({why})" if why else ""))\n        fid = uuid.uuid4().hex[:8]\n        path = f"drafts/{did}/files/{fid}_{_slug(name)}"\n        store.put(path, data)\n        fr = formula_sheet_refs(data, name) if hint == "output" else {"referenced": set()}\n        ent = {"fid": fid, "name": name, "path": path, "sheets": [], "issues": report}\n        for i, s in enumerate(sheets):\n            role = hint if hint in ROLES and hint != "ignore" else guess_role(name, s["sheet"], s["n_formulas"], i == 0)\n            if guess_role(name, s["sheet"], s["n_formulas"], i == 0) == "ignore" and hint in ("input", "mapping"):\n                role = "ignore"     # data dictionaries / notes sheets are not data\n            if hint == "output":\n                role = "output"\n                # an output workbook often carries the mapping sheets its formulas use\n                if fr["referenced"] and s["sheet"] in fr["referenced"]:\n                    role = "mapping"\n                elif any(x["n_formulas"] for x in sheets) and not s["n_formulas"]                         and guess_role("", s["sheet"], 0, False) == "mapping":\n                    role = "mapping"      # value-only sheet called Rates / Lookup / Mapping next to formula sheets\n            ent["sheets"].append({"sheet": s["sheet"], "role": role, "n_formulas": s["n_formulas"],\n                                  "header_row": s["header_row"], **summarize(s["df"])})\n        entries.append(ent)\n    with _DRAFT_LOCK:                          # tiny read-modify-write: never lose a concurrent upload\n        d = get_draft(store, did)\n        d["files"].extend(entries)\n        put_json(store, f"drafts/{did}/draft.json", d)\n    return d\n\n\ndef set_draft_roles(store, did: str, roles: Dict[str, str]) -> Dict[str, Any]:\n    with _DRAFT_LOCK:\n        d = get_draft(store, did)\n        for f in d["files"]:\n            for s in f["sheets"]:\n                k = f"{f[\'fid\']}|{s[\'sheet\']}"\n                if k in roles and roles[k] in ROLES:\n                    s["role"] = roles[k]\n        put_json(store, f"drafts/{did}/draft.json", d)\n        return d\n\n\ndef remove_draft_file(store, did: str, fid: str) -> Dict[str, Any]:\n    with _DRAFT_LOCK:\n        d = get_draft(store, did)\n        for f in d["files"]:\n            if f["fid"] == fid:\n                store.delete(f["path"])\n        d["files"] = [f for f in d["files"] if f["fid"] != fid]\n        put_json(store, f"drafts/{did}/draft.json", d)\n        return d\n\n\ndef _entries(store, files: List[Dict[str, Any]]) -> List[Dict[str, Any]]:\n    out = []\n    for f in files:\n        data = store.get(f["path"])\n        if data is None:\n            raise ValueError(f"stored file missing: {f[\'name\']}")\n        roles = {s["sheet"]: s["role"] for s in f["sheets"]}\n        for s in read_workbook(data, f["name"]):\n            role = roles.get(s["sheet"], "ignore")\n            if role == "ignore":\n                continue\n            out.append({"file": f["name"], "sheet": s["sheet"], "role": role, "df": s["df"],\n                        "header_row": s["header_row"], "n_formulas": s["n_formulas"], "bytes": data,\n                        "col_offset": s.get("col_offset", 0), "grid": s.get("grid"),\n                        "col_idx": s.get("col_idx"), "formula_cells": s.get("formula_cells")})\n    return out\n\n\n# ===================================================================== systems\nINDEX = "index.json"\n\n\ndef _read_index(store) -> Dict[str, Any]:\n    idx = get_json(store, INDEX)\n    if idx is None:  # first run, or index lost: rebuild from the system folders\n        idx = {"systems": {}}\n        for p in store.list("systems/"):\n            if p.endswith("/system.json"):\n                sid = p.split("/")[-2]\n                try:\n                    idx["systems"][sid] = system_card(get_system(store, sid))\n                except Exception:  # noqa: BLE001\n                    continue\n        put_json(store, INDEX, idx)\n    return idx\n\n\ndef list_systems(store) -> List[Dict[str, Any]]:\n    res = list(_read_index(store)["systems"].values())\n    res.sort(key=lambda s: s.get("updated") or s.get("created") or "", reverse=True)\n    return res\n\n\ndef system_card(s: Dict[str, Any]) -> Dict[str, Any]:\n    sheets = s.get("sheets", [])\n    n_formula = sum(1 for d in sheets for c in d["columns"] if c["kind"] == "formula")\n    n_empty = sum(1 for d in sheets for c in d["columns"] if c["kind"] == "empty")\n    sp = s.get("filters", {}).get("split", {})\n    return {"id": s["id"], "name": s["name"], "description": s.get("description", ""),\n            "created": s.get("created"), "updated": s.get("updated"),\n            "n_sheets": len(sheets), "n_formulas": n_formula, "n_review": n_empty,\n            "n_tables": len(s.get("tables", {})), "split": bool(sp.get("enabled")),\n            "columns": sum(len(d["columns"]) for d in sheets)}\n\n\ndef _tslug(name: str) -> str:\n    return re.sub(r"[^A-Za-z0-9._-]+", "_", name)[:80] or "table"\n\n\ndef get_system(store, sid: str) -> Dict[str, Any]:\n    """Assemble a system from its files: system.json + rules.json + tables/<name>.json."""\n    s = get_json(store, f"systems/{sid}/system.json")\n    if s is None:\n        raise KeyError("system not found")\n    if "sheets" not in s:\n        s["sheets"] = (get_json(store, f"systems/{sid}/template.json") or {}).get("sheets", [])\n    if "tables" not in s:  # (older systems kept everything inline - handled by the `in` checks)\n        s["tables"] = {}\n        for name, fn in (s.get("table_files") or {}).items():\n            t = get_json(store, f"systems/{sid}/tables/{fn}.json")\n            if t is not None:\n                s["tables"][name] = t\n    return s\n\n\ndef save_system(store, s: Dict[str, Any]) -> None:\n    """Readable layout in the folder:\n        index.json                       one card per system (fast home page)\n        systems/<id>/system.json         name, input/output layout, filters, toggles, training info\n        systems/<id>/template.json       every output sheet: its columns, formulas, parameter cells\n        systems/<id>/tables/<name>.json  one file per mapping table (rewritten only when changed)\n    """\n    import hashlib\n    import json as _json\n    s["updated"] = _now()\n    sid = s["id"]\n    base = f"systems/{sid}"\n    tables = s.get("tables", {})\n    files = {n: _tslug(n) for n in tables}\n    hashes = dict(s.get("table_hashes") or {})\n    for n, spec in tables.items():\n        h = hashlib.md5(_json.dumps(spec, sort_keys=True, default=str).encode("utf-8")).hexdigest()\n        if hashes.get(n) != h or store.get(f"{base}/tables/{files[n]}.json") is None:\n            put_json(store, f"{base}/tables/{files[n]}.json", spec, indent=1)\n            hashes[n] = h\n    for old in set(hashes) - set(tables):\n        store.delete(f"{base}/tables/{_tslug(old)}.json")\n        hashes.pop(old, None)\n    lean = {k: v for k, v in s.items() if k not in ("sheets", "tables")}\n    lean["table_files"], lean["table_hashes"] = files, hashes\n    put_json(store, f"{base}/template.json", {"sheets": s.get("sheets", [])}, indent=1)\n    put_json(store, f"{base}/system.json", lean, indent=1)\n    idx = _read_index(store)\n    idx["systems"][sid] = system_card(s)\n    put_json(store, INDEX, idx)\n\n\ndef delete_system(store, sid: str) -> None:\n    delete_prefix(store, f"systems/{sid}/")\n    delete_prefix(store, f"runs/{sid}/")\n    idx = _read_index(store)\n    idx["systems"].pop(sid, None)\n    put_json(store, INDEX, idx)\n\n\ndef create_system(store, did: str, options: Dict[str, Any]) -> Dict[str, Any]:\n    d = get_draft(store, did)\n    system = engine.build_system(_entries(store, d["files"]), options)\n    sid = system["id"]\n    files = []                       # keep the example files with the system so it can be re-learned later\n    for f in d["files"]:\n        newp = f"systems/{sid}/training/{f[\'fid\']}_{_slug(f[\'name\'])}"\n        store.put(newp, store.get(f["path"]))\n        files.append({**f, "path": newp})\n    put_json(store, f"systems/{sid}/training.json", {"files": files})\n    delete_prefix(store, f"drafts/{did}/")\n    save_system(store, system)\n    return get_system(store, sid)\n\n\ndef relearn(store, sid: str, options: Dict[str, Any]) -> Dict[str, Any]:\n    s = get_system(store, sid)\n    tr = get_json(store, f"systems/{sid}/training.json")\n    opts = {"name": s["name"], "description": s.get("description", ""), "id": sid}\n    opts.update(options or {})\n    new = engine.build_system(_entries(store, tr["files"]), opts)\n    new["created"] = s.get("created", new["created"])\n    save_system(store, new)\n    return get_system(store, sid)\n\n\ndef update_system(store, sid: str, patch: Dict[str, Any]) -> Dict[str, Any]:\n    s = get_system(store, sid)\n    for k in ("name", "description"):\n        if k in patch:\n            s[k] = str(patch[k])\n    for k in ("filters", "toggles"):\n        if k in patch:\n            s[k] = patch[k]\n    if patch.get("formulas"):\n        engine.apply_formula_edits(s, patch["formulas"])\n    if patch.get("dtypes"):\n        engine.apply_dtype_edits(s, patch["dtypes"])\n    if "tables" in patch:  # replace mapping tables (e.g. refreshed rates)\n        for n, spec in patch["tables"].items():\n            s["tables"][n] = spec\n    engine.finalize_system(s)\n    save_system(store, s)\n    return s\n\n\ndef _read_inputs(system: Dict[str, Any], files: List[Tuple[str, bytes]]\n                 ) -> Tuple[pd.DataFrame, List[str], List[Dict[str, Any]]]:\n    cols = system["input"]["columns"]\n    want = {nk(c) for c in cols if c != engine.SRC}\n    req = {nk(c) for c in system["input"].get("required", []) if c != engine.SRC}\n    frames, used = [], []\n    for name, data in files:\n        scored = []\n        for s in read_workbook(data, name):\n            have = {nk(c) for c in s["df"].columns}\n            scored.append((len(want & have) / max(1, len(want)), req <= have, s))\n        good = [s for sc, ok, s in scored if sc >= 0.6 and ok and len(s["df"])]\n        if not good:\n            best = max(scored, key=lambda t: t[0]) if scored else None\n            miss = sorted((want | req) - {nk(c) for c in best[2]["df"].columns}) if best else []\n            raise ValueError(f"{name}: no sheet looks like the input this system was built from "\n                             f"(missing e.g. {\', \'.join(miss[:6])}).")\n        multi = engine.SRC in cols\n        for s in (good if multi else sorted(good, key=lambda x: -len(x["df"]))[:1]):\n            f = canonical_columns(s["df"], cols)\n            if multi:   # the input\'s own sheets are the split; keep each row\'s sheet name\n                f = f.copy()\n                f[engine.SRC] = s["sheet"]\n            frames.append(f)\n            used.append({"file": name, "sheet": s["sheet"], "rows": int(len(s["df"]))})\n    return pd.concat(frames, ignore_index=True), [], used\n\n\ndef run_system(store, sid: str, input_files: List[Tuple[str, bytes]],\n               mapping_files: Optional[List[Tuple[str, bytes]]] = None,\n               toggle_values: Optional[Dict[str, str]] = None) -> Dict[str, Any]:\n    s = get_system(store, sid)\n    df, _, used = _read_inputs(s, input_files)\n    override = {}\n    for name, data in mapping_files or []:\n        for sh in read_workbook(data, name):\n            for tname in s["tables"]:\n                if nk(tname) == nk(sh["sheet"]) or nk(tname) == nk(re.sub(r"\\.[^.]+$", "", name)):\n                    override[tname] = sh["df"]\n    res = engine.apply_system(s, df, override, toggle_values)\n    notes = list(res["notes"])\n    if override:\n        notes.append("Mapping tables replaced for this run: " + ", ".join(override))\n    empty = [c["name"] for d in s["sheets"] for c in d["columns"] if c["kind"] == "empty"]\n    if empty:\n        notes.append("No formula was found in your sample for: " + ", ".join(dict.fromkeys(empty)) + " - left empty.")\n    tg = {t["name"]: t.get("value") for t in res["toggles"]}\n    summary = [("Toggles used", ", ".join("%s = %s" % kv for kv in tg.items()) or "none"),\n               ("Input files", [f"{u[\'file\']} / {u[\'sheet\']} ({u[\'rows\']} rows)" for u in used])]\n    if notes:\n        summary.append(("Notes", notes))\n    tables = engine.tables_to_frames(s, override)\n    data = engine.write_workbook(s, res["sheets"], summary, tables, res["toggles"])\n    rid = dt.datetime.utcnow().strftime("%Y%m%d-%H%M%S") + "-" + uuid.uuid4().hex[:4]\n    store.put(f"runs/{sid}/{rid}/output.xlsx", data)\n    preview = {}\n    for sn, item in res["sheets"].items():\n        f = item["df"]\n        preview[sn] = {"rows": int(len(f)), "headers": list(map(str, f.columns)),\n                       "kinds": [c["kind"] for c in item["def"]["columns"]],\n                       "data": [[jsonable(v) for v in r] for r in f.head(25).itertuples(index=False, name=None)]}\n    meta = {"run_id": rid, "system": sid, "created": _now(), "rows": int(res["rows"]),\n            "input_rows": int(res["input_rows"]), "sheets": {k: v["rows"] for k, v in preview.items()},\n            "notes": notes, "inputs": used, "toggles": res["toggles"],\n            "filename": f"{_slug(s[\'name\'])}_{rid}.xlsx"}\n    put_json(store, f"runs/{sid}/{rid}/meta.json", meta)\n    return {**meta, "preview": preview}\n\n\ndef list_runs(store, sid: str) -> List[Dict[str, Any]]:\n    out = []\n    for p in store.list(f"runs/{sid}/"):\n        if p.endswith("/meta.json"):\n            m = get_json(store, p.lstrip("/"))\n            if m:\n                m.pop("compare", None)\n                out.append(m)\n    out.sort(key=lambda m: m["created"], reverse=True)\n    return out[:30]\n\n\ndef get_run_file(store, sid: str, rid: str) -> Tuple[bytes, str]:\n    data = store.get(f"runs/{sid}/{rid}/output.xlsx")\n    meta = get_json(store, f"runs/{sid}/{rid}/meta.json") or {}\n    if data is None:\n        raise KeyError("run not found")\n    return data, meta.get("filename", f"{rid}.xlsx")\n\n\ndef input_template(system: Dict[str, Any]) -> bytes:\n    import openpyxl\n    wb = openpyxl.Workbook()\n    ws = wb.active\n    ws.title = "Input"\n    ws.append([c for c in system["input"]["columns"] if c != engine.SRC])\n    buf = io.BytesIO()\n    wb.save(buf)\n    return buf.getvalue()\n')

"""**Category Replicator** - Dataiku Standard webapp, Python pane.

Teach a *category* from examples (input file(s) + mapping file(s) + the expected output) and the
app learns a rule for every output column - copy, lookup into a mapping, arithmetic, concat,
IF/bands, date parts, or the live Excel formula itself.  Run the category on new data to get the
same output back, optionally split into several sheets by a filter.

Needs ``replicator_formulas`` and ``replicator`` on the project's Python libraries (both in ``python-lib/``).
Storage: one managed folder whose id is the project variable ``REPLICATOR_FOLDER`` (see store.py).
"""


import io
import traceback
from functools import wraps

from flask import Response, jsonify, request

from replicator import service
from replicator.engine import ENGINE_BUILD
from replicator.store import make_store

try:  # pragma: no cover - Dataiku provides `app`
    app  # type: ignore  # noqa: F821
except NameError:  # pragma: no cover
    from flask import Flask
    app = Flask(__name__)

# ---- GLOBAL SETTING: the managed folder where systems, mappings, rules and runs are saved.
# Put the folder's name or id here. If left empty, the project variable REPLICATOR_FOLDER is used.
REPLICATOR_FOLDER = ""

_STORE = None
_MAX_UPLOAD = 200 * 1024 * 1024


def store():
    global _STORE
    if _STORE is None:
        try:
            _STORE = make_store(REPLICATOR_FOLDER)
        except TypeError:  # stale replicator/store.py in the project libraries: use the env fallback
            import os
            if REPLICATOR_FOLDER:
                os.environ["REPLICATOR_FOLDER"] = REPLICATOR_FOLDER
            _STORE = make_store()
    return _STORE


def ok(**kw):
    kw["success"] = True
    return jsonify(kw)


def fail(msg, code=400, details=None):
    return jsonify({"success": False, "error": str(msg), "details": details}), code


def guarded(fn):
    @wraps(fn)
    def wrapper(*a, **kw):
        try:
            return fn(*a, **kw)
        except KeyError as exc:
            return fail(exc.args[0] if exc.args else "not found", 404)
        except ValueError as exc:
            return fail(exc)
        except Exception as exc:  # noqa: BLE001
            return fail(f"{type(exc).__name__}: {exc}", 500, traceback.format_exc()[-1500:])
    return wrapper


def _files(field="files"):
    out = []
    for f in request.files.getlist(field):
        if f and f.filename:
            data = f.read()
            if len(data) > _MAX_UPLOAD:
                raise ValueError(f"{f.filename} is too large")
            out.append((f.filename, data))
    return out


def _download(data, name, mime="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"):
    return Response(data, mimetype=mime, headers={
        "Content-Disposition": 'attachment; filename="%s"' % name, "Content-Length": str(len(data))})


# ---------------------------------------------------------------------------- routes
@app.route("/api/health", methods=["GET"])
@guarded
def api_health():
    return ok(engine_build=ENGINE_BUILD, storage=type(store()).__name__)


@app.route("/api/systems", methods=["GET"])
@guarded
def api_systems():
    return ok(systems=service.list_systems(store()))


@app.route("/api/drafts", methods=["POST"])
@guarded
def api_new_draft():
    return ok(draft_id=service.new_draft(store()))


@app.route("/api/drafts/<did>", methods=["GET"])
@guarded
def api_get_draft(did):
    return ok(draft=service.get_draft(store(), did))


@app.route("/api/drafts/<did>/files", methods=["POST"])
@guarded
def api_draft_files(did):
    d = service.add_draft_files(store(), did, _files(), request.form.get("hint", ""))
    return ok(draft=d)


@app.route("/api/drafts/<did>/files/<fid>", methods=["DELETE"])
@guarded
def api_draft_file_delete(did, fid):
    return ok(draft=service.remove_draft_file(store(), did, fid))


@app.route("/api/drafts/<did>/roles", methods=["PUT"])
@guarded
def api_draft_roles(did):
    return ok(draft=service.set_draft_roles(store(), did, (request.get_json(silent=True) or {}).get("roles", {})))


@app.route("/api/drafts/<did>/learn", methods=["POST"])
@guarded
def api_learn(did):
    body = request.get_json(silent=True) or {}
    s = service.create_system(store(), did, {
        "name": (body.get("name") or "").strip() or "Untitled system",
        "description": body.get("description", ""), "split": body.get("split") or {"mode": "auto"}})
    return ok(system=s)


@app.route("/api/systems/<sid>", methods=["GET"])
@guarded
def api_system(sid):
    return ok(system=service.get_system(store(), sid))


@app.route("/api/systems/<sid>", methods=["PUT"])
@guarded
def api_system_update(sid):
    return ok(system=service.update_system(store(), sid, request.get_json(silent=True) or {}))


@app.route("/api/systems/<sid>", methods=["DELETE"])
@guarded
def api_system_delete(sid):
    service.delete_system(store(), sid)
    return ok()


@app.route("/api/systems/<sid>/relearn", methods=["POST"])
@guarded
def api_relearn(sid):
    body = request.get_json(silent=True) or {}
    return ok(system=service.relearn(store(), sid, {"split": body.get("split") or {"mode": "auto"}}))


@app.route("/api/systems/<sid>/run", methods=["POST"])
@guarded
def api_run(sid):
    inputs = _files("files")
    if not inputs:
        raise ValueError("Upload at least one input file.")
    import json as _json
    try:
        tv = _json.loads(request.form.get("toggles") or "{}")
    except ValueError:
        tv = {}
    res = service.run_system(store(), sid, inputs, _files("mappings"), tv or None)
    return ok(run=res)


@app.route("/api/systems/<sid>/runs", methods=["GET"])
@guarded
def api_runs(sid):
    return ok(runs=service.list_runs(store(), sid))


@app.route("/api/systems/<sid>/runs/<rid>/download", methods=["GET"])
@guarded
def api_run_download(sid, rid):
    data, name = service.get_run_file(store(), sid, rid)
    return _download(data, name)


@app.route("/api/systems/<sid>/template", methods=["GET"])
@guarded
def api_template(sid):
    s = service.get_system(store(), sid)
    return _download(service.input_template(s), "%s_input_template.xlsx" % s["name"])


@app.route("/api/systems/<sid>/tables/<tname>/download", methods=["GET"])
@guarded
def api_table_download(sid, tname):
    import openpyxl
    s = service.get_system(store(), sid)
    spec = s["tables"][tname]
    wb = openpyxl.Workbook()
    ws = wb.active
    ws.title = tname[:31]
    ws.append(spec["headers"])
    for r in spec["records"]:
        ws.append([r.get(h) for h in spec["headers"]])
    buf = io.BytesIO()
    wb.save(buf)
    return _download(buf.getvalue(), "%s.xlsx" % tname)
